SEVERITY_ORDER = ["info", "low", "medium", "high", "critical"]



def max_severity(a, b):
    """Return the stronger of two severity labels (by rank)."""
    return a if SEV_RANK.get(a, 0) >= SEV_RANK.get(b, 0) else b


def vuln_boosted_severity(base, max_sev, kev=False, kev_ransomware=False):
    """Effective severity for an alert whose process is tied to vulnerable software on the host: the
    worst of the alert's own severity and the vulnerability's, with a known-exploited (KEV) floor —
    a flaw being exploited in the wild outranks a theoretical score. Only ever raises, never lowers."""
    floor = "critical" if kev_ransomware else ("high" if kev else "info")
    eff = max_severity(base or "info", max_sev or "info")
    return max_severity(eff, floor)


def severity_for(score):
    if score >= 70:
        return "high"
    if score >= 40:
        return "medium"
    if score >= 20:
        return "low"
    return "info"


# ---------------------------------------------------------------------------
# Small subprocess helper
# ---------------------------------------------------------------------------

def run(cmd, timeout=15, env=None):
    """Run a command, return (returncode, stdout, stderr) as text; never raise."""
    try:
        p = subprocess.run(cmd, capture_output=True, text=True, timeout=timeout, env=env)
        return p.returncode, p.stdout, p.stderr
    except subprocess.TimeoutExpired:
        return 124, "", "timeout"
    except Exception as e:  # noqa: BLE001
        return 1, "", str(e)


def _proc_env_for_uid(uid, want=("DBUS_SESSION_BUS_ADDRESS", "DISPLAY", "WAYLAND_DISPLAY",
                                 "XDG_RUNTIME_DIR")):
    """Best-effort: read a live graphical process's session env for `uid` from /proc (so we get the
    EXACT dbus address the desktop is using, even on non-standard setups)."""
    try:
        pids = os.listdir("/proc")
    except OSError:
        return {}
    for pid in pids:
        if not pid.isdigit():
            continue
        try:
            if os.stat(f"/proc/{pid}").st_uid != uid:
                continue
            with open(f"/proc/{pid}/environ", "rb") as f:
                raw = f.read()
        except OSError:
            continue
        env = {}
        for kv in raw.split(b"\x00"):
            if b"=" in kv:
                k, v = kv.split(b"=", 1)
                ks = k.decode("utf-8", "replace")
                if ks in want:
                    env[ks] = v.decode("utf-8", "replace")
        if "DBUS_SESSION_BUS_ADDRESS" in env:      # a real desktop session, not a stray daemon
            return env
    return {}


def _desktop_target():
    """When the agent runs as root, resolve the logged-in graphical user's session so a notification
    can be delivered TO them (root's own `notify-send` reaches no user session bus). Returns
    (uid, gid, name, env) or None to just deliver directly (already a normal user, or headless)."""
    if os.geteuid() != 0:
        return None                                # not root: our own session is the user's
    cand = []
    su = os.environ.get("SUDO_USER")               # the user who ran `sudo …` — usually the desktop user
    if su and su != "root":
        try:
            cand.append(pwd.getpwnam(su).pw_uid)
        except KeyError:
            pass
    try:
        for d in sorted(os.listdir("/run/user")):  # any user with a systemd runtime dir (a live session)
            if d.isdigit() and int(d) not in cand:
                cand.append(int(d))
    except OSError:
        pass
    for uid in cand:
        if uid < 1000:                             # skip system accounts
            continue
        try:
            pw = pwd.getpwuid(uid)
        except KeyError:
            continue
        scanned = _proc_env_for_uid(uid)
        bus = scanned.get("DBUS_SESSION_BUS_ADDRESS")
        if not bus and os.path.exists(f"/run/user/{uid}/bus"):
            bus = f"unix:path=/run/user/{uid}/bus"
        if not bus:
            continue
        env = {"DBUS_SESSION_BUS_ADDRESS": bus,
               "XDG_RUNTIME_DIR": scanned.get("XDG_RUNTIME_DIR") or f"/run/user/{uid}",
               "HOME": pw.pw_dir, "USER": pw.pw_name, "LOGNAME": pw.pw_name,
               "PATH": "/usr/bin:/bin:/usr/local/bin"}
        for k in ("DISPLAY", "WAYLAND_DISPLAY"):
            if scanned.get(k):
                env[k] = scanned[k]
        return uid, pw.pw_gid, pw.pw_name, env
    return None


def _loopback_http(url):
    """True only for a plain http:// URL pointing at loopback — the only thing we hand to a
    notification's click-to-open (never an arbitrary or remote URL)."""
    try:
        u = urllib.parse.urlparse(url or "")
        return u.scheme == "http" and (u.hostname or "") in ("127.0.0.1", "localhost", "::1")
    except Exception:  # noqa: BLE001
        return False


def _session_preexec(tgt):
    """A preexec_fn that becomes the target graphical user (root -> that user), or None when not needed."""
    if tgt is None:
        return None
    uid, gid, name, _env = tgt

    def _drop():
        os.setgid(gid)
        try:
            os.initgroups(name, gid)
        except (OSError, PermissionError):
            pass
        os.setuid(uid)
    return _drop


def notify_push(title, body, severity=None):
    push = globals().get("_PUSH")
    if push is not None:
        try:
            push.send(title, body, severity)
        except Exception:  # noqa: BLE001
            pass


def notify_all(title, body, subtitle=None, severity=None):
    """Desktop banner + wearable push (best-effort) — used by backend-initiated notifications.
    Mirrors the macOS agent so anything raised from the snapshot path behaves the same on both."""
    notify_desktop(title, body, subtitle)
    notify_push(title, (subtitle + " \u2014 " + body) if subtitle else body, severity)


def notify_desktop(title, body, subtitle=None, url=None):
    """Post a desktop notification via notify-send (libnotify). Best-effort. When running as root,
    delivers to the logged-in graphical user's session rather than root's (which has no daemon). When
    `url` is a loopback Scouter link, the banner gets a clickable "Open in Scouter" action that
    xdg-opens it in that session (on a background thread, since notify-send --action blocks until the
    banner is actioned or closed). Degrades to a plain banner where the daemon lacks action support."""
    if subtitle:
        body = f"{subtitle}\n{body}" if body else subtitle
    tgt = _desktop_target()
    env = tgt[3] if tgt else None
    clickable = bool(url and _loopback_http(url))
    args = ["notify-send", "-a", "Linux Scouter"]
    if clickable:
        args += ["--action=open=Open in Scouter"]
    args += [title, body or ""]

    if not clickable:
        try:
            p = subprocess.run(args, env=env, preexec_fn=_session_preexec(tgt),
                               capture_output=True, text=True, timeout=5)
            return p.returncode == 0
        except Exception:  # noqa: BLE001
            return False

    def _wait_and_open():
        # notify-send --action blocks until the user activates the action (prints its key) or the
        # banner closes; if our "open" action fired, launch the deep link in the user's session.
        try:
            p = subprocess.run(args, env=env, preexec_fn=_session_preexec(tgt),
                               capture_output=True, text=True, timeout=180)
        except Exception:  # noqa: BLE001
            return
        if (p.stdout or "").strip() == "open":
            try:
                subprocess.run(["xdg-open", url], env=env, preexec_fn=_session_preexec(tgt),
                               capture_output=True, text=True, timeout=10)
            except Exception:  # noqa: BLE001
                pass
    threading.Thread(target=_wait_and_open, daemon=True).start()
    return True


def is_private_ip(ip):
    try:
        a = ipaddress.ip_address(ip)
        return a.is_private or a.is_loopback or a.is_link_local or a.is_multicast or a.is_reserved
    except ValueError:
        return True  # hostnames / "*" — treat as non-public for scoring


def proc_excluded_from_ip_vt(p, extra=()):
    """True if this process's outbound IPs should be skipped for VirusTotal lookups
    (e.g. Google Chrome Helper). Matched as a substring of the executable path."""
    exe = (p.get("exe") or "").lower()
    return any(s.lower() in exe for s in list(VT_IP_EXCLUDE_PROCS) + list(extra))


def is_loopback_addr(ip):
    if ip in ("127.0.0.1", "::1", "localhost"):
        return True
    try:
        return ipaddress.ip_address(ip).is_loopback
    except ValueError:
        return False


# ---------------------------------------------------------------------------
# Collectors
# ---------------------------------------------------------------------------

# Linux process accounting units (jiffies, pages) used to derive %CPU / %MEM the
# same way `ps` does, read straight from /proc so we get the real exe path.
_CLK_TCK = os.sysconf("SC_CLK_TCK") if hasattr(os, "sysconf") else 100
_PAGESIZE = os.sysconf("SC_PAGE_SIZE") if hasattr(os, "sysconf") else 4096


def _total_ram_kb(_cache=[]):
    """MemTotal from /proc/meminfo, in KiB (cached; used for %MEM)."""
    if _cache:
        return _cache[0]
    total = 0
    try:
        with open("/proc/meminfo") as fh:
            for line in fh:
                if line.startswith("MemTotal:"):
                    total = int(line.split()[1])
                    break
    except OSError:
        pass
    _cache.append(total or 1)
    return _cache[0]


def _system_uptime():
    """Seconds since boot, from /proc/uptime (for elapsed/%CPU)."""
    try:
        with open("/proc/uptime") as fh:
            return float(fh.read().split()[0])
    except (OSError, ValueError, IndexError):
        return 0.0


def _fmt_etime(secs):
    """Format elapsed seconds the way `ps etime` does: [[DD-]HH:]MM:SS."""
    secs = int(max(secs, 0))
    days, rem = divmod(secs, 86400)
    hours, rem = divmod(rem, 3600)
    mins, sec = divmod(rem, 60)
    if days:
        return f"{days}-{hours:02d}:{mins:02d}:{sec:02d}"
    if hours:
        return f"{hours:02d}:{mins:02d}:{sec:02d}"
    return f"{mins:02d}:{sec:02d}"


def _read_proc(pid, name):
    try:
        with open(f"/proc/{pid}/{name}", "rb") as fh:
            return fh.read()
    except (OSError, ValueError):
        return None


def collect_processes():
    """Return {pid: {pid, ppid, uid, user, cpu, mem, state, elapsed, exe, cmdline, argv}}.

    Reads /proc directly: /proc/<pid>/stat for the accounting fields, /exe for the
    real backing binary (incl. the " (deleted)" marker), /cmdline for argv as the
    process presents it, and the dir owner for the uid. %CPU/%MEM are derived to
    match `ps` (lifetime average CPU, RSS / physical memory).
    """
    procs = {}
    uptime = _system_uptime()
    total_ram_kb = _total_ram_kb()
    try:
        pids = [int(e) for e in os.listdir("/proc") if e.isdigit()]
    except OSError:
        return procs

    for pid in pids:
        stat_raw = _read_proc(pid, "stat")
        if not stat_raw:
            continue
        s = stat_raw.decode("utf-8", "replace")
        # comm sits in parens and may itself contain spaces/parens; bracket on the
        # first '(' and the last ')' so the surrounding fields parse cleanly.
        lp, rp = s.find("("), s.rfind(")")
        if lp < 0 or rp < 0 or rp < lp:
            continue
        comm = s[lp + 1:rp]
        f = s[rp + 2:].split()
        if len(f) < 22:
            continue
        try:
            state = f[0]
            ppid = int(f[1])
            utime, stime = int(f[11]), int(f[12])
            starttime = int(f[19])
            rss_pages = int(f[21])
        except (ValueError, IndexError):
            continue

        # uid/user from the /proc/<pid> directory owner (the real uid).
        try:
            uid = os.stat(f"/proc/{pid}").st_uid
        except OSError:
            continue
        try:
            user = pwd.getpwuid(uid).pw_name
        except KeyError:
            user = str(uid)

        # Real backing executable (may be unreadable for other users' procs when
        # we're not root → fall back to comm; keeps the " (deleted)" anti-forensics tell).
        try:
            exe = os.readlink(f"/proc/{pid}/exe")
        except OSError:
            exe = ""

        # argv exactly as the process presents it (argv[0] may be spoofed → masquerade signal).
        cmd_raw = _read_proc(pid, "cmdline") or b""
        argv_all = [a for a in cmd_raw.decode("utf-8", "replace").split("\0") if a]
        if argv_all:
            cmdline = " ".join(argv_all)
            argv = argv_all[1:]
        else:
            # kernel threads / zombies have an empty cmdline; show the comm in brackets.
            cmdline = f"[{comm}]"
            argv = []

        proc_uptime = max(uptime - (starttime / _CLK_TCK), 1e-3) if uptime else 1e-3
        cpu = 100.0 * ((utime + stime) / _CLK_TCK) / proc_uptime
        mem = 100.0 * (rss_pages * _PAGESIZE / 1024.0) / total_ram_kb

        procs[pid] = {
            "pid": pid, "ppid": ppid, "uid": str(uid), "user": user,
            "cpu": f"{cpu:.1f}", "mem": f"{mem:.1f}", "state": state,
            "elapsed": _fmt_etime(proc_uptime),
            "cmdline": cmdline, "exe": exe, "argv": argv,
        }
    return procs


# /proc/net/tcp state column (hex) -> ps/lsof-style name. UDP rows have no state.
_TCP_STATES = {
    "01": "ESTABLISHED", "02": "SYN_SENT", "03": "SYN_RECV", "04": "FIN_WAIT1",
    "05": "FIN_WAIT2", "06": "TIME_WAIT", "07": "CLOSE", "08": "CLOSE_WAIT",
    "09": "LAST_ACK", "0A": "LISTEN", "0B": "CLOSING",
}


def _hex_to_ip(hexaddr):
    """Decode a /proc/net little-endian hex address (IPv4 = 8 chars, IPv6 = 32)."""
    try:
        b = bytes.fromhex(hexaddr)
    except ValueError:
        return ""
    if len(b) == 4:                       # IPv4: bytes are little-endian
        return ".".join(str(x) for x in reversed(b))
    if len(b) == 16:                      # IPv6: four 32-bit words, each little-endian
        raw = b"".join(b[i:i + 4][::-1] for i in range(0, 16, 4))
        try:
            return socket.inet_ntop(socket.AF_INET6, raw)
        except OSError:
            return ""
    return ""


def _socket_inode_to_pid():
    """Map socket inode -> owning pid by scanning /proc/<pid>/fd symlinks.

    Without root we can only read our own processes' fds, so unattributed sockets
    are dropped — the same visibility limit the macOS build had without sudo.
    """
    mapping = {}
    try:
        pids = [e for e in os.listdir("/proc") if e.isdigit()]
    except OSError:
        return mapping
    for pid in pids:
        fd_dir = f"/proc/{pid}/fd"
        try:
            fds = os.listdir(fd_dir)
        except OSError:
            continue
        for fd in fds:
            try:
                target = os.readlink(f"{fd_dir}/{fd}")
            except OSError:
                continue
            if target.startswith("socket:["):
                mapping[target[8:-1]] = int(pid)
    return mapping


def _parse_proc_net(path, proto):
    """Yield connection records from a /proc/net/{tcp,tcp6,udp,udp6} table."""
    try:
        with open(path) as fh:
            lines = fh.readlines()[1:]   # skip header row
    except OSError:
        return
    for line in lines:
        parts = line.split()
        if len(parts) < 10:
            continue
        l_hex, _, r_hex = parts[1].partition(":")
        r_addr_hex, _, r_port_hex = parts[2].partition(":")
        st = _TCP_STATES.get(parts[3].upper(), "") if proto.startswith("TCP") else ""
        inode = parts[9]
        laddr = _hex_to_ip(l_hex)
        lport = str(int(r_hex, 16)) if r_hex else ""
        raddr = _hex_to_ip(r_addr_hex)
        rport = str(int(r_port_hex, 16)) if r_port_hex else ""
        # A zero remote (0.0.0.0:0 / [::]:0) means "no peer" — a listener/bound socket.
        if rport in ("", "0") and (not raddr or set(raddr) <= set(".0:")):
            raddr, rport = "", ""
        yield inode, {"proto": proto, "laddr": laddr, "lport": lport,
                      "raddr": raddr, "rport": rport, "state": st}


def collect_network():
    """Return {pid: [ {proto, laddr, lport, raddr, rport, state}, ... ]}.

    Parses /proc/net/{tcp,tcp6,udp,udp6} and attributes each socket to its owning
    process via the inode->pid map (stdlib only; no lsof/ss dependency). Sockets we
    can't attribute to a readable process are skipped.
    """
    conns = {}
    inode_pid = _socket_inode_to_pid()
    tables = [
        ("/proc/net/tcp", "TCP"), ("/proc/net/tcp6", "TCP"),
        ("/proc/net/udp", "UDP"), ("/proc/net/udp6", "UDP"),
    ]
    for path, proto in tables:
        for inode, rec in _parse_proc_net(path, proto):
            pid = inode_pid.get(inode)
            if pid is None or not (rec["lport"] or rec["rport"]):
                continue
            conns.setdefault(pid, []).append(rec)
    return conns


def _expand_cron_command(line, system=False):
    """Strip the schedule (and user, for system crontab) fields, return the command."""
    fields = 6 if system else 5
    parts = line.split(None, fields)
    return parts[fields] if len(parts) > fields else line


# systemd unit search paths (highest precedence first — /etc overrides vendor units).
SYSTEM_UNIT_DIRS = ["/etc/systemd/system", "/run/systemd/system",
                    "/usr/lib/systemd/system", "/lib/systemd/system"]
USER_UNIT_DIRS = ["/etc/systemd/user", "/usr/lib/systemd/user", "/lib/systemd/user"]
# Vendor unit dirs are distro-shipped — dampened (analog of the macOS /System dampener).
VENDOR_UNIT_PREFIXES = ("/usr/lib/systemd/", "/lib/systemd/")


def _strip_exec_prefix(tok):
    """Drop the systemd ExecStart special prefixes (@ - : + ! !!) from a token."""
    return tok.lstrip("@-:+!")


def _parse_systemd_unit(path):
    """Minimal INI read of a unit file — just the fields we surface in the graph."""
    info = {"Description": "", "ExecStart": "", "WantedBy": "",
            "OnCalendar": "", "OnBootSec": "", "OnUnitActiveSec": ""}
    try:
        with open(path, encoding="utf-8", errors="replace") as fh:
            for raw in fh:
                line = raw.strip()
                if not line or line.startswith(("#", ";")) or line.startswith("["):
                    continue
                key, sep, val = line.partition("=")
                if not sep:
                    continue
                key, val = key.strip(), val.strip()
                if key in info and not info[key] and val:   # first non-empty wins
                    info[key] = val
    except OSError:
        return None
    return info


def _systemd_enabled_units(user=False):
    """Set of unit names enabled via .wants/.requires symlinks (no systemctl spawn)."""
    enabled = set()
    bases = ([os.path.expanduser("~/.config/systemd/user"), "/etc/systemd/user"]
             if user else ["/etc/systemd/system"])
    for base in bases:
        for link in (glob.glob(os.path.join(base, "*.wants", "*")) +
                     glob.glob(os.path.join(base, "*.requires", "*"))):
            enabled.add(os.path.basename(link))
    return enabled


def collect_persistence():
    """Return a list of job dicts: cron entries + systemd units/timers.

    Linux persistence loci that map to a per-snapshot graph 'job' node. Broader,
    diffed surfaces (XDG autostart, ld.so.preload, rc files) are handled by the
    background PersistenceCollector.
    """
    jobs = []
    euid = os.geteuid()

    # --- cron ---
    cron_sources = []                                    # (path, owner, is_system[, text])
    if euid == 0:                                        # per-user crontabs (Debian/Ubuntu)
        for f in sorted(glob.glob("/var/spool/cron/crontabs/*")):
            cron_sources.append((f, os.path.basename(f), False))
    else:
        rc, out, _ = run(["crontab", "-l"], timeout=5)
        if rc == 0 and out.strip():
            cron_sources.append((None, os.environ.get("USER", "you"), False, out))
    if os.path.exists("/etc/crontab"):
        cron_sources.append(("/etc/crontab", "system", True))
    for f in sorted(glob.glob("/etc/cron.d/*")):
        cron_sources.append((f, "cron.d", True))

    for src in cron_sources:
        path, owner, system = src[0], src[1], src[2]
        try:
            text = src[3] if len(src) > 3 else open(path, "r", errors="replace").read()
        except OSError:
            continue
        mtime = os.path.getmtime(path) if path and os.path.exists(path) else None
        for raw in text.splitlines():
            line = raw.strip()
            if not line or line.startswith("#"):
                continue
            first = line.split()[0]
            if "=" in first:                             # env assignment (PATH=…, SHELL=…)
                continue
            command = _expand_cron_command(line, system=system)
            jobs.append({
                "kind": "cron", "label": f"cron ({owner})", "owner": owner,
                "program": command, "argv": [], "raw": line, "path": path,
                "mtime": mtime, "run_at_load": True,
                "schedule": line[: len(line) - len(command)].strip(),
            })

    # run-parts script dirs: each executable is a scheduled job in its own right.
    for period in ("hourly", "daily", "weekly", "monthly"):
        for f in sorted(glob.glob(f"/etc/cron.{period}/*")):
            if os.path.isdir(f) or os.path.basename(f) in (".placeholder", "00-header"):
                continue
            try:
                mtime = os.path.getmtime(f)
            except OSError:
                mtime = None
            jobs.append({
                "kind": "cron", "label": f"cron.{period}", "owner": "system",
                "program": f, "argv": [], "raw": f, "path": f, "mtime": mtime,
                "run_at_load": True, "schedule": period,
            })

    # --- systemd units (services + timers) ---
    scopes = [(SYSTEM_UNIT_DIRS, False)]
    home_user_dir = os.path.expanduser("~/.config/systemd/user")
    scopes.append(([home_user_dir] + USER_UNIT_DIRS, True))
    for dirs, is_user in scopes:
        enabled = _systemd_enabled_units(user=is_user)
        seen = set()
        for d in dirs:
            for f in sorted(glob.glob(os.path.join(d, "*.service")) +
                            glob.glob(os.path.join(d, "*.timer"))):
                unit = os.path.basename(f)
                if unit in seen:                         # /etc override already won
                    continue
                seen.add(unit)
                info = _parse_systemd_unit(f)
                if info is None:
                    continue
                is_timer = unit.endswith(".timer")
                exec_tokens = info["ExecStart"].split()
                program = _strip_exec_prefix(exec_tokens[0]) if exec_tokens else ""
                argv = exec_tokens[1:]
                try:
                    mtime = os.path.getmtime(f)
                except OSError:
                    mtime = None
                if is_timer:
                    schedule = (info["OnCalendar"] or info["OnBootSec"] or
                                info["OnUnitActiveSec"] or "timer")
                else:
                    schedule = "enabled" if unit in enabled else "static/disabled"
                owner = "user" if (is_user or f.startswith(home_user_dir)) else "system"
                jobs.append({
                    "kind": "systemd-timer" if is_timer else "systemd",
                    "label": info["Description"] or unit,
                    "owner": owner, "program": program, "argv": argv,
                    "raw": (info["ExecStart"] or unit).strip(),
                    "path": f, "mtime": mtime,
                    "run_at_load": (unit in enabled) or bool(info["OnBootSec"]),
                    "schedule": schedule,
                })
    return jobs


# ---------------------------------------------------------------------------
# Code-signature checks (cached, threaded)
# ---------------------------------------------------------------------------

class DpkgIndex:
    """Lazy, cached index of dpkg's own metadata — the Linux analog of code signing.

    Builds path->package from /var/lib/dpkg/info/*.list and verifies integrity against
    the package's recorded MD5s in /var/lib/dpkg/info/*.md5sums. All read from disk,
    so no per-file `dpkg-query`/`dpkg -V` subprocess spawns.
    """
    INFO_DIR = "/var/lib/dpkg/info"

    def __init__(self):
        self.lock = threading.Lock()
        self._path_pkg = None        # absolute path -> package name (without :arch)

    def _build(self):
        path_pkg = {}
        try:
            names = os.listdir(self.INFO_DIR)
        except OSError:
            self._path_pkg = {}
            return
        for name in names:
            if not name.endswith(".list"):
                continue
            pkg = name[:-5].split(":", 1)[0]   # strip ".list" and any :arch suffix
            try:
                with open(os.path.join(self.INFO_DIR, name), encoding="utf-8",
                          errors="replace") as fh:
                    for line in fh:
                        p = line.rstrip("\n")
                        if p:
                            path_pkg[p] = pkg
            except OSError:
                continue
        self._path_pkg = path_pkg

    def package_for(self, path):
        with self.lock:
            if self._path_pkg is None:
                self._build()
        pkg = self._path_pkg.get(path)
        if pkg is None:
            rp = os.path.realpath(path)
            if rp != path:
                pkg = self._path_pkg.get(rp)
        return pkg

    def recorded_md5(self, pkg, path):
        """The MD5 dpkg recorded for `path` in `pkg`, or None if not listed/conffile."""
        rel = path.lstrip("/")
        for cand in (f"{pkg}.md5sums",):
            fn = os.path.join(self.INFO_DIR, cand)
            try:
                with open(fn, encoding="utf-8", errors="replace") as fh:
                    for line in fh:
                        md5, _, p = line.partition("  ")
                        if p.strip() == rel:
                            return md5.strip()
            except OSError:
                pass
        # multiarch md5sums file (pkg:arch.md5sums)
        try:
            for fn in glob.glob(os.path.join(self.INFO_DIR, f"{pkg}:*.md5sums")):
                with open(fn, encoding="utf-8", errors="replace") as fh:
                    for line in fh:
                        md5, _, p = line.partition("  ")
                        if p.strip() == rel:
                            return md5.strip()
        except OSError:
            pass
        return None


class SignatureChecker:
    """Classify an executable by package provenance + integrity (Linux).

    Categories (chosen to map onto the existing scorer/graph semantics):
      packaged   — owned by an installed dpkg package, integrity verified (trusted)
      modified   — owned by a package but its on-disk MD5 no longer matches (tamper)
      unpackaged — not owned by any package (locally built, pip/npm, AppImage, …)
      missing    — path does not exist on disk
    """
    def __init__(self, enabled=True):
        self.enabled = enabled
        self.cache = {}  # (path, mtime, size) -> result dict
        self.lock = threading.Lock()
        self.dpkg = DpkgIndex()

    def _classify(self, path):
        try:
            st = os.stat(path)
            key = (path, int(st.st_mtime), st.st_size)
        except OSError:
            return {"category": "missing", "trusted": False, "detail": "binary not found"}
        with self.lock:
            if key in self.cache:
                return self.cache[key]

        pkg = self.dpkg.package_for(path)
        if pkg is None:
            result = {"category": "unpackaged", "trusted": False,
                      "detail": "not from an installed package"}
        else:
            recorded = self.dpkg.recorded_md5(pkg, path)
            if recorded is None:
                # listed by the package but no MD5 on record (e.g. a conffile) — trust it.
                result = {"category": "packaged", "trusted": True,
                          "detail": f"{pkg} (unverified)"}
            elif hash_file_md5(path) == recorded:
                result = {"category": "packaged", "trusted": True, "detail": pkg}
            else:
                result = {"category": "modified", "trusted": False,
                          "detail": f"{pkg} file modified since install"}

        with self.lock:
            self.cache[key] = result
        return result

    def check_many(self, paths):
        out = {}
        if not self.enabled:
            return {p: {"category": "unknown", "trusted": True, "detail": "sig checks disabled"} for p in paths}
        paths = [p for p in paths if p and p.startswith("/")]
        if not paths:
            return out
        with ThreadPoolExecutor(max_workers=8) as ex:
            for path, res in zip(paths, ex.map(self._classify, paths)):
                out[path] = res
        return out


# ---------------------------------------------------------------------------
# Local file hashing (MD5 + SHA-256), computed once per (path, mtime, size)
# ---------------------------------------------------------------------------

def hash_file(path):
    """Stream a file and return {'md5','sha256'} (local, no network), or None on error."""
    md5, sha = hashlib.md5(), hashlib.sha256()
    try:
        with open(path, "rb") as f:
            for chunk in iter(lambda: f.read(1 << 20), b""):
                md5.update(chunk)
                sha.update(chunk)
        return {"md5": md5.hexdigest(), "sha256": sha.hexdigest()}
    except OSError:
        return None


def hash_file_md5(path):
    """MD5 hex digest of a file, or None on error (used for dpkg integrity checks)."""
    md5 = hashlib.md5()
    try:
        with open(path, "rb") as f:
            for chunk in iter(lambda: f.read(1 << 20), b""):
                md5.update(chunk)
        return md5.hexdigest()
    except OSError:
        return None


class HashCache:
    """Streams each process binary once to compute md5+sha256, cached and threaded.

    get() returns the cached hashes immediately, or None while a background hash
    is still in flight (the next snapshot will pick it up). All local — no network.
    """
    SYNC_MAX_BYTES = 64 * 1024 * 1024   # only hash inline (blocking) for files up to this size

    def __init__(self, enabled=True):
        self.enabled = enabled
        self.cache = {}        # (path, mtime, size) -> {"md5":..., "sha256":...}
        self.inflight = set()
        self.lock = threading.Lock()
        self.ex = ThreadPoolExecutor(max_workers=4) if enabled else None

    def get(self, path, sync=False):
        """Return cached hashes, else None (async — next snapshot picks it up). With sync=True
        and a reasonably-sized file, hash it INLINE so the result is available THIS snapshot —
        used for newly-seen executables in suspicious locations so an IOC hash hit can floor the
        severity to high immediately instead of a snapshot or two later."""
        if not self.enabled or not path or not path.startswith("/"):
            return None
        try:
            st = os.stat(path)
            key = (path, int(st.st_mtime), st.st_size)
        except OSError:
            return None
        with self.lock:
            if key in self.cache:
                return self.cache[key]
            already_inflight = key in self.inflight
            if not already_inflight:
                self.inflight.add(key)
        if sync and not already_inflight and st.st_size <= self.SYNC_MAX_BYTES:
            res = hash_file(path)                 # blocking — small/high-risk binaries only
            with self.lock:
                self.inflight.discard(key)
                if res:
                    self.cache[key] = res
            return res
        if already_inflight:
            return None
        self.ex.submit(self._hash, path, key)
        return None

    def _hash(self, path, key):
        res = hash_file(path)
        with self.lock:
            self.inflight.discard(key)
            if res:
                self.cache[key] = res


# ---------------------------------------------------------------------------
# VirusTotal enrichment — looks up ONLY newly-identified hashes / public IPs,
# rate-limited, cached, in a background worker. Enabled only when VT_API_KEY set.
# ---------------------------------------------------------------------------

class VTClient:
    KEY_ENV = "VT_API_KEY"

    def __init__(self, secrets=None, rpm=4, daily_cap=480, cache_file=None, usage_file=None,
                 settings_file=None, ip_mode="signal"):
        self.secrets = secrets or SecretStore()
        self.key = ""
        self.key_source = None          # 'keychain' | 'file' | 'env' | None
        self.enabled = False
        self.rpm = max(1, rpm)
        self.daily_cap = daily_cap
        self.cache = {}        # (kind, value) -> result dict
        # self-managed priority queue so it can be viewed / cancelled / reprioritized
        self.pending = {}      # (kind, value) -> {kind, value, priority, seq, enqueued}
        self.inflight = None   # (kind, value) currently being looked up
        self.seq = 0
        self.lock = threading.Lock()
        self.cv = threading.Condition(self.lock)   # shares self.lock
        self.count = 0         # lookups performed this run
        self.cache_file = cache_file or os.path.join(HERE, "vt-cache.json")
        self.usage_file = usage_file or os.path.join(HERE, "vt-usage.json")
        self.usage = {}        # 'YYYY-MM-DD' (UTC) -> our API calls that day (local fallback)
        self.quota = None      # authoritative quota from VT: {daily,hourly,monthly,fetched}
        self.calls_since_quota = 0   # our calls since the last VT quota sync (bridges between fetches)
        self.quota_interval = 1800   # re-sync VT quota every 30 min
        self.settings_file = settings_file or os.path.join(HERE, "vt-settings.json")
        # IP lookup policy:
        #   'all'    – look up every newly-seen public IP (best for Enterprise/high-quota keys)
        #   'signal' – only look up an IP that already matches another signal (suspicious
        #              connection, IOC feed hit, or flagged owning process) — saves quota
        self.ip_mode = ip_mode if ip_mode in ("all", "signal") else "signal"
        self._load_cache()     # persisted verdicts survive restarts (keeps e.g. Mimikatz=high)
        self._load_usage()
        self._load_settings()  # a GUI-set ip_mode (vt-settings.json) overrides the CLI default
        self._resolve_key()    # key from the Keychain/0600 file (GUI-set) or VT_API_KEY env
        # Worker + quota threads always run; they idle while disabled or with no pending work,
        # so a key entered later in the GUI takes effect immediately (no relaunch).
        threading.Thread(target=self._worker, daemon=True).start()
        threading.Thread(target=self._quota_loop, daemon=True).start()

    # ---- API key (GUI-settable, stored in the SecretStore; env is a read-only fallback) ----
    def _resolve_key(self):
        stored = self.secrets.get("vt")
        if stored:
            self.key, self.key_source = stored, self.secrets.backend_for("vt")
        else:
            env = os.environ.get(self.KEY_ENV, "").strip()
            self.key, self.key_source = (env, "env") if env else ("", None)
        self.enabled = bool(self.key)

    def set_key(self, key):
        """Store (or clear, if empty) the VT key in the SecretStore and re-resolve. Never echoes it."""
        if self.key_source == "env":
            return {"ok": False, "error": f"key comes from ${self.KEY_ENV} — unset the "
                                          f"environment variable to manage it in the GUI"}
        backend = self.secrets.set("vt", key)
        self._resolve_key()
        if self.enabled:
            threading.Thread(target=self._sync_quota, daemon=True).start()
        return {"ok": True, "stored": bool((key or "").strip()), "backend": backend}

    # ---- IP lookup mode (GUI-settable, persisted to vt-settings.json) ----
    def _load_settings(self):
        try:
            with open(self.settings_file) as f:
                d = json.load(f) or {}
        except (OSError, ValueError):
            return
        if d.get("ip_mode") in ("all", "signal"):
            self.ip_mode = d["ip_mode"]

    def _save_settings(self):
        try:
            with open(self.settings_file, "w") as f:
                json.dump({"ip_mode": self.ip_mode}, f)
        except OSError:
            pass

    def set_ip_mode(self, mode):
        """Switch the IP lookup policy ('all' vs 'signal') and persist it. Cheap, takes effect
        on the next snapshot."""
        mode = (mode or "").strip().lower()
        if mode not in ("all", "signal"):
            return {"ok": False, "error": "mode must be 'all' or 'signal'"}
        with self.lock:
            self.ip_mode = mode
        self._save_settings()
        return {"ok": True, "ip_mode": mode}

    def _sync_quota(self):
        q = self._fetch_quota()
        if q:
            with self.lock:
                self.quota = q
                self.calls_since_quota = 0

    def feed_entry(self):
        """VT presented as the first row of the Threat-Intel list (key flow mirrors IOC feeds)."""
        with self.cv:
            used, allowed, _ = self._used_allowed_nolock()
            queued = len(self.pending)
        return {"id": "vt", "name": "VirusTotal", "vt": True,
                "desc": "Live hash & public-IP reputation lookups (sends only hashes / public IPs, "
                        "never file contents). Matched IOC feeds are checked first to save quota.",
                "kinds": ["hash", "ip"], "parser": "live", "severity": "high",
                "on": self.enabled, "auth": True, "has_key": bool(self.key),
                "key_source": self.key_source, "key_env": self.KEY_ENV,
                "key_editable": self.key_source != "env", "configured": True,
                "count": None, "last_fetched": None, "last_error": None, "fetching": False,
                "tos": "https://www.virustotal.com/", "custom": False,
                "today": used, "cap": allowed, "queued": queued, "scanned": self.count,
                "ip_mode": self.ip_mode}

    # VT's API request quota resets daily at 00:00 UTC — match that for the local fallback count
    @staticmethod
    def _today_utc():
        return time.strftime("%Y-%m-%d", time.gmtime())

    def _load_usage(self):
        try:
            with open(self.usage_file) as f:
                d = json.load(f)
            if isinstance(d, dict):
                self.usage = {k: int(v) for k, v in d.items() if isinstance(v, (int, float))}
        except (OSError, ValueError):
            self.usage = {}

    def _bump_usage(self):
        """One real API request was made — count it locally + against the VT-quota bridge."""
        with self.lock:
            self.calls_since_quota += 1
            day = self._today_utc()
            self.usage[day] = self.usage.get(day, 0) + 1
            for k in sorted(self.usage)[:-14]:    # keep ~14 days
                self.usage.pop(k, None)
            try:
                tmp = self.usage_file + ".tmp"
                with open(tmp, "w") as f:
                    json.dump(self.usage, f)
                os.replace(tmp, self.usage_file)
            except OSError:
                pass

    # ---- authoritative quota from VirusTotal (license-aware, VT's own reset) ----
    def _fetch_quota(self):
        try:
            req = urllib.request.Request(VT_API + f"/users/{self.key}/overall_quotas",
                                         headers={"x-apikey": self.key})
            with urllib.request.urlopen(req, timeout=15) as r:
                data = json.load(r)
        except Exception:  # noqa: BLE001
            return None
        d = data.get("data") or {}

        def pick(name):
            u = (d.get(name) or {}).get("user") or {}
            return {"allowed": u["allowed"], "used": u.get("used", 0)} if u.get("allowed") is not None else None
        daily = pick("api_requests_daily")
        if not daily:
            return None
        return {"daily": daily, "hourly": pick("api_requests_hourly"),
                "monthly": pick("api_requests_monthly"), "fetched": time.time()}

    def _quota_loop(self):
        while True:
            if self.enabled:
                q = self._fetch_quota()
                if q:
                    with self.lock:
                        self.quota = q
                        self.calls_since_quota = 0   # VT's 'used' is now authoritative; reset the bridge
            time.sleep(self.quota_interval if self.enabled else 60)

    def _used_allowed_nolock(self):
        """Returns (used_today, allowed_today, source). Caller must hold self.lock."""
        q = self.quota
        if q and q.get("daily") and (time.time() - q.get("fetched", 0) < self.quota_interval * 3):
            return (q["daily"]["used"] + self.calls_since_quota, q["daily"]["allowed"], "virustotal")
        allowed = q["daily"]["allowed"] if (q and q.get("daily")) else self.daily_cap
        return (self.usage.get(self._today_utc(), 0), allowed, "local")

    def usage_status(self):
        with self.lock:
            used, allowed, source = self._used_allowed_nolock()
            q = self.quota or {}
            return {"used": used, "allowed": allowed, "source": source,
                    "remaining": max(0, allowed - used),
                    "hourly": q.get("hourly"), "monthly": q.get("monthly"),
                    "quota_age": (round(time.time() - q["fetched"]) if q.get("fetched") else None)}

    def day_count(self):
        with self.lock:
            return self._used_allowed_nolock()[0]

    def _load_cache(self):
        try:
            with open(self.cache_file) as f:
                d = json.load(f)
            for k, v in d.items():
                kind, _, value = k.partition("|")
                if value:
                    self.cache[(kind, value)] = v
        except (OSError, ValueError):
            pass

    def _save_cache(self):
        try:
            d = {f"{kind}|{value}": res for (kind, value), res in self.cache.items()
                 if isinstance(res, dict) and res.get("status") in ("done", "notfound")}
            tmp = self.cache_file + ".tmp"
            with open(tmp, "w") as f:
                json.dump(d, f)
            os.replace(tmp, self.cache_file)
        except OSError:
            pass

    def get(self, kind, value):
        with self.lock:
            return self.cache.get((kind, value))

    def enqueue(self, kind, value, priority=10):
        """Queue a lookup if we've never seen this item. No-op once cached/queued.
        Lower `priority` jumps the line — downloads/manual scans use 0."""
        if not self.enabled or not value:
            return
        k = (kind, value)
        with self.cv:
            if k in self.cache or k in self.pending:   # done/queued/cancelled/inflight all block re-add
                return
            used, allowed, _ = self._used_allowed_nolock()
            if used >= allowed:                          # daily quota reached
                self.cache[k] = {"status": "capped"}
                return
            self.seq += 1
            self.pending[k] = {"kind": kind, "value": value, "priority": priority,
                               "seq": self.seq, "enqueued": time.time()}
            self.cache[k] = {"status": "queued"}
            self.cv.notify()

    # ---- queue management (view / cancel / reprioritize / rescan) ----
    def queue_view(self):
        with self.cv:
            now = time.time()
            items = sorted(self.pending.values(), key=lambda it: (it["priority"], it["seq"]))
            pending = [{"kind": it["kind"], "value": it["value"], "priority": it["priority"],
                        "waiting": round(now - it["enqueued"], 1)} for it in items]
            infl = ({"kind": self.inflight[0], "value": self.inflight[1]} if self.inflight else None)
            used, allowed, source = self._used_allowed_nolock()
            q = self.quota or {}
            return {"enabled": self.enabled, "pending": pending, "inflight": infl,
                    "scanned": self.count, "rpm": self.rpm,
                    "today": used, "cap": allowed, "remaining": max(0, allowed - used),
                    "source": source, "hourly": q.get("hourly"), "monthly": q.get("monthly")}

    def cancel(self, kind, value):
        k = (kind, value)
        with self.cv:
            if k in self.pending:
                del self.pending[k]
                self.cache[k] = {"status": "cancelled"}   # sticks (won't be auto-re-queued)
                return True
        return False

    def cancel_all(self):
        with self.cv:
            n = len(self.pending)
            for k in list(self.pending):
                self.cache[k] = {"status": "cancelled"}
            self.pending.clear()
            return n

    def reprioritize(self, kind, value, priority):
        k = (kind, value)
        with self.cv:
            if k in self.pending:
                self.seq += 1
                self.pending[k]["priority"] = priority
                self.pending[k]["seq"] = self.seq
                self.cv.notify()
                return True
        return False

    def rescan(self, kind, value):
        """Force a fresh lookup (clears any cached/cancelled verdict), at the front."""
        with self.cv:
            self.cache.pop((kind, value), None)
            self.pending.pop((kind, value), None)
        self.enqueue(kind, value, priority=0)

    def stats(self):
        with self.cv:
            used, allowed, source = self._used_allowed_nolock()
            return {"scanned": self.count, "queued": len(self.pending),
                    "cap": allowed, "today": used, "source": source}

    def _next_pending(self):
        """Block until there's a pending item AND we're under the daily quota, then pop the
        highest-priority one. (The timeout lets us re-check after the quota resets/refreshes.)"""
        with self.cv:
            while not (self.pending and self._used_allowed_nolock()[0] < self._used_allowed_nolock()[1]):
                self.cv.wait(timeout=30)
            key = min(self.pending, key=lambda k: (self.pending[k]["priority"], self.pending[k]["seq"]))
            item = self.pending.pop(key)
            self.inflight = key
            self.cache[key] = {"status": "looking-up"}
            return key, item

    def _worker(self):
        interval = 60.0 / self.rpm
        while True:
            key, item = self._next_pending()
            res = self._lookup(item["kind"], item["value"])
            self._bump_usage()        # a real API request was made (counts toward the daily quota)
            if res.get("status") == "ratelimited":
                with self.cv:
                    self.inflight = None
                    if key not in self.cache or self.cache[key].get("status") == "looking-up":
                        self.pending[key] = item       # requeue unless cancelled meanwhile
                        self.cache[key] = {"status": "queued"}
                        self.cv.notify()
                time.sleep(interval * 3)
                continue
            with self.cv:
                self.inflight = None
                self.cache[key] = res
                self.count += 1
            if res.get("status") in ("done", "notfound"):
                self._save_cache()    # persist terminal verdicts
            time.sleep(interval)

    def _lookup(self, kind, value):
        path = f"/files/{value}" if kind == "file" else f"/ip_addresses/{value}"
        req = urllib.request.Request(VT_API + path, headers={"x-apikey": self.key})
        try:
            with urllib.request.urlopen(req, timeout=20) as r:
                data = json.load(r)
        except urllib.error.HTTPError as e:
            if e.code == 404:
                return {"status": "notfound", "malicious": 0}
            if e.code == 429:
                return {"status": "ratelimited"}
            if e.code in (401, 403):
                return {"status": "error", "error": "VT auth failed (check VT_API_KEY)"}
            return {"status": "error", "error": f"HTTP {e.code}"}
        except Exception as e:  # noqa: BLE001
            return {"status": "error", "error": str(e)}
        return parse_vt(data)


def parse_vt(data):
    """Distil a VirusTotal v3 file/ip response into our compact result dict."""
    attr = (data.get("data") or {}).get("attributes", {}) or {}
    stats = attr.get("last_analysis_stats", {}) or {}
    results = attr.get("last_analysis_results", {}) or {}
    mal = int(stats.get("malicious", 0) or 0)
    susp = int(stats.get("suspicious", 0) or 0)
    total = sum(v for v in stats.values() if isinstance(v, int))
    names, pua = [], 0
    for info in results.values():
        if info.get("category") in ("malicious", "suspicious"):
            nm = info.get("result") or ""
            names.append(nm)
            if PUA_RE.search(nm):
                pua += 1
    frac = round(pua / len(names), 3) if names else 0.0
    return {"status": "done", "malicious": mal, "suspicious": susp, "total": total,
            "pua": pua, "pua_fraction": frac, "names": names[:30],
            "fetched": time.strftime("%H:%M:%S")}


def apply_vt_severity(score, reasons, vt, is_file):
    """Fold a finished VT result into a node's score/reasons per the alert rules."""
    if not vt or vt.get("status") != "done":
        return score
    mal = vt.get("malicious", 0)
    if mal > VT_MALICIOUS_THRESHOLD:
        if is_file and vt.get("pua_fraction", 0) > VT_PUA_FRACTION:
            reasons.append(reason(
                f"VirusTotal: {mal} vendors flag this file, mostly PUA/PUP "
                f"({int(vt['pua_fraction'] * 100)}% of detections)", "T1204.002", 0))
            return max(score, 50)            # floor at medium
        label = "file" if is_file else "IP"
        reasons.append(reason(
            f"VirusTotal: {mal} vendors flag this {label} as malicious",
            "T1204.002" if is_file else "T1071", 0))
        return max(score, 90)               # floor at high
    if mal > 0:
        reasons.append(reason(
            f"VirusTotal: {mal} vendor(s) flagged (below the {VT_MALICIOUS_THRESHOLD}-vendor alert threshold)",
            None, 0))
    return score


def host_from_url(u):
    """Best-effort hostname out of a URL or bare host string (stdlib only)."""
    if not u:
        return ""
    try:
        netloc = urllib.parse.urlsplit(u if "://" in u else "//" + u).netloc
    except ValueError:
        netloc = u
    host = (netloc or u).split("@")[-1]          # strip user:pass@
    host = host.split(":")[0].strip().strip("/")  # strip :port
    return host.lower()


class SecretStore:
    """Stores feed API keys as securely as the host allows.

    Prefers the **Secret Service** (the system keyring — GNOME Keyring / KWallet) via the
    `secret-tool` CLI (libsecret), which encrypts secrets at rest and unlocks them with your
    login session. Falls back to a `0600` file (`ioc-secrets.json`, readable only by your user)
    when secret-tool isn't installed or the keyring can't be reached (e.g. a headless / SSH boot).
    Running as root (sudo), the keyring targeted is the *logged-in* user's, not root's. Secrets
    are **never** written to ioc-feeds.json and **never** sent to the browser (the UI only ever
    sees a has-key bool). The 'keychain' backend label is kept for cross-platform UI parity."""

    SERVICE = "LinuxScouter"

    def __init__(self, file_path=None, keychain=True):
        # keychain=False forces the file backend. Passing only file_path does NOT isolate a store:
        # the Secret Service stays primary, so a throwaway instance writes into the REAL keyring.
        self.file_path = file_path or os.path.join(HERE, "ioc-secrets.json")
        self._st = shutil.which("secret-tool") if keychain else None   # Secret Service CLI; None -> file
        if os.environ.get("SCOUTER_DAEMON"):
            # The background service reads secrets only from its root-only 0600 file. A user's
            # Secret Service keyring exists only inside their login session, so at boot there is
            # nothing to read — secrets would appear only after someone logged in, and vanish again.
            self._st = None
        self._st_ready = None                          # lazily-probed keyring reachability (cached)
        self._cache = {}                               # fid -> secret (this run)
        self._backend = {}                             # fid -> 'keychain'|'file'|None

    @property
    def keychain(self):
        return self._keyring_usable()

    def _keyring_run(self, args, input_text=None, timeout=10):
        """Run secret-tool against the Secret Service. When we are root, run it AS the logged-in
        graphical user (root has no session keyring), reusing the same session resolution as desktop
        notifications. Returns the CompletedProcess, or None if the keyring can't be reached (no
        secret-tool, headless, locked, or timeout) so the caller falls back to the 0600 file."""
        if not self._st:
            return None
        try:
            if os.geteuid() != 0:
                return subprocess.run([self._st] + args, input=input_text,
                                      capture_output=True, text=True, timeout=timeout)
            tgt = _desktop_target()
            if not tgt:
                return None
            uid, gid, name, env = tgt

            def _drop():
                os.setgid(gid)
                try:
                    os.initgroups(name, gid)
                except (OSError, PermissionError):
                    pass
                os.setuid(uid)

            return subprocess.run([self._st] + args, input=input_text, env=env,
                                  preexec_fn=_drop, capture_output=True, text=True, timeout=timeout)
        except Exception:  # noqa: BLE001
            return None

    def _keyring_usable(self):
        """Lazily probe (once per run) whether the Secret Service is actually reachable: a lookup of
        a nonexistent item returns rc 0/1 when the service is up, or None/other when it isn't."""
        if self._st_ready is None:
            r = self._keyring_run(["lookup", "service", self.SERVICE, "account", "__probe__"])
            self._st_ready = bool(r is not None and r.returncode in (0, 1))
        return self._st_ready

    def _acct(self, fid):
        return f"ioc:{fid}"

    def _load_file(self):
        try:
            with open(self.file_path) as f:
                d = json.load(f)
            return d if isinstance(d, dict) else {}
        except (OSError, ValueError):
            return {}

    def _save_file(self, d):
        try:
            if d:
                fd = os.open(self.file_path, os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o600)
                with os.fdopen(fd, "w") as f:
                    json.dump(d, f)
                os.chmod(self.file_path, 0o600)        # belt-and-suspenders on existing file
            elif os.path.exists(self.file_path):
                os.remove(self.file_path)              # don't leave an empty secrets file around
            return True
        except OSError:
            return False

    def get(self, fid):
        if fid in self._cache:
            return self._cache[fid] or None
        secret, backend = None, None
        if self._keyring_usable():
            r = self._keyring_run(["lookup", "service", self.SERVICE, "account", self._acct(fid)])
            if r is not None and r.returncode == 0 and r.stdout:
                secret, backend = r.stdout.rstrip("\n"), "keychain"
        if secret is None:
            fv = self._load_file().get(fid)
            if fv:
                secret, backend = fv, "file"
        self._cache[fid] = secret
        self._backend[fid] = backend
        return secret or None

    def set(self, fid, secret):
        """Store (or, with an empty value, clear) a key. Returns the backend used."""
        secret = (secret or "").strip()
        if not secret:
            self.delete(fid)
            return None
        self._cache[fid] = secret
        if self._keyring_usable():
            r = self._keyring_run(["store", "--label", "Linux Scouter API key",
                                   "service", self.SERVICE, "account", self._acct(fid)],
                                  input_text=secret)     # secret read from stdin, never argv
            if r is not None and r.returncode == 0:
                # Verify it reads back — a keyring write can succeed yet be unreadable later (locked /
                # session change). If it isn't readable, fall through to the 0600 file so it persists.
                chk = self._keyring_run(["lookup", "service", self.SERVICE, "account", self._acct(fid)])
                if chk is not None and chk.returncode == 0 and (chk.stdout or "").rstrip("\n") == secret:
                    d = self._load_file()                # readable → drop any plaintext fallback copy
                    if d.pop(fid, None) is not None:
                        self._save_file(d)
                    self._backend[fid] = "keychain"
                    return "keychain"
        d = self._load_file(); d[fid] = secret            # fallback: 0600 file
        ok = self._save_file(d)
        self._backend[fid] = "file" if ok else None
        return "file" if ok else None

    def delete(self, fid):
        self._cache.pop(fid, None)
        self._backend[fid] = None
        if self._keyring_usable():
            self._keyring_run(["clear", "service", self.SERVICE, "account", self._acct(fid)])
        d = self._load_file()
        if d.pop(fid, None) is not None:
            self._save_file(d)
        return True

    def backend_for(self, fid):
        """Where this feed's key lives ('keychain'|'file'|None) — for UI display only."""
        if fid not in self._backend:
            self.get(fid)                                # populates _backend (cached)
        return self._backend.get(fid)


class IOCFeeds:
    """Pulls open threat-intel feeds (STIX/TAXII + IOC lists) and matches indicators
    locally — no per-item external lookup, works with VirusTotal off. Feeds are
    individually toggleable (persisted to ioc-feeds.json) and cached to disk so a
    relaunch is instant and offline-tolerant."""

    SEV_RANK = {"low": 1, "medium": 2, "high": 3}
    # What a user-added feed may use. We deliberately expose only the generic,
    # format-driven parsers (not publisher-specific CSV shapes).
    CUSTOM_PARSERS = {"plaintext", "hashlist", "cidr", "stix_bundle", "taxii21"}
    CUSTOM_KINDS = {"ip", "domain", "url", "hash"}

    def __init__(self, enabled=True, interval=21600, config_file=None, cache_file=None,
                 secrets=None, custom_file=None):
        self.enabled = enabled
        self.interval = max(900, interval)            # don't hammer publishers
        self.config_file = config_file or os.path.join(HERE, "ioc-feeds.json")
        self.cache_file = cache_file or os.path.join(HERE, "ioc-cache.json")
        self.custom_file = custom_file or os.path.join(HERE, "ioc-custom-feeds.json")
        self.secrets = secrets or SecretStore()
        self.lock = threading.Lock()
        # indicator indexes: kind -> {normalized_value -> [hit, ...]}
        self.idx = {"ip": {}, "hash": {}, "domain": {}, "url": {}}
        self.cidr = []                                # [(ip_network, hit), ...]
        self.feeds = {}                               # id -> merged catalog+config dict
        self.state = {}                               # id -> {count,last_fetched,last_error,fetching}
        self._build_feeds()
        self._load_cache()
        if self.enabled:
            threading.Thread(target=self._refresh_loop, daemon=True).start()

    # ---- catalog / config ----
    def _build_feeds(self):
        overrides = {}
        try:
            with open(self.config_file) as f:
                overrides = json.load(f) or {}
        except (OSError, ValueError):
            overrides = {}
        migrated = False
        for spec in IOC_FEED_CATALOG:
            f = dict(spec)
            f["on"] = f.pop("default", False)
            ov = overrides.get(f["id"], {})
            if isinstance(ov, dict):
                if "on" in ov:
                    f["on"] = bool(ov["on"])
                for k in ("url", "collection"):            # non-secret overrides only
                    if ov.get(k):
                        f[k] = ov[k]
                # MIGRATE any legacy plaintext key out of ioc-feeds.json into the SecretStore,
                # then drop it from the file (it is stripped on the next _save_config below).
                if ov.get("api_key"):
                    self.secrets.set(f["id"], ov["api_key"])
                    migrated = True
            self.feeds[f["id"]] = f
            self.state.setdefault(f["id"], {"count": 0, "last_fetched": None,
                                            "last_error": None, "fetching": False})
            self._resolve_key(f)
        if migrated:
            self._save_config()                           # rewrite without the plaintext key
        self._load_custom_feeds()                         # then layer on user-defined feeds

    # ---- user-defined ("custom") feeds ----
    def _load_custom_feeds(self):
        """Load feeds the operator added themselves (ioc-custom-feeds.json). Each is
        validated through the same gate as the add API, so a hand-edited or stale
        entry can't inject an unsupported parser/kind."""
        try:
            with open(self.custom_file) as fh:
                arr = json.load(fh) or []
        except (OSError, ValueError):
            return
        if not isinstance(arr, list):
            return
        for spec in arr:
            if not isinstance(spec, dict):
                continue
            ok, res = self._validate_spec(spec)
            if not ok:
                continue
            fid = (spec.get("id") or "").strip() or self._make_id(res["name"])
            if not fid.startswith("user_"):
                fid = "user_" + fid
            res["id"], res["custom"], res["on"] = fid, True, bool(spec.get("on", False))
            self.feeds[fid] = res
            self.state.setdefault(fid, {"count": 0, "last_fetched": None,
                                        "last_error": None, "fetching": False})
            self._resolve_key(res)

    def _make_id(self, name):
        slug = re.sub(r"[^a-z0-9]+", "_", (name or "").lower()).strip("_")[:24] or "feed"
        base, fid, n = "user_" + slug, "user_" + slug, 2
        while fid in self.feeds:
            fid = f"{base}_{n}"; n += 1
        return fid

    def _validate_spec(self, spec):
        """Validate + normalize a feed spec from the UI or the custom file.
        Returns (True, normalized_dict) or (False, error_message)."""
        name = (spec.get("name") or "").strip()
        if not name or len(name) > 80:
            return False, "name is required (≤80 chars)"
        parser = (spec.get("parser") or "").strip()
        if parser not in self.CUSTOM_PARSERS:
            return False, "parser must be one of: " + ", ".join(sorted(self.CUSTOM_PARSERS))
        url = (spec.get("url") or "").strip()
        u = urllib.parse.urlparse(url)
        if u.scheme not in ("http", "https") or not u.netloc:
            return False, "url must be a valid http(s):// address"
        kinds = spec.get("kinds") or []
        if parser == "cidr":
            kinds = ["ip"]
        if (not isinstance(kinds, list) or not kinds
                or any(k not in self.CUSTOM_KINDS for k in kinds)):
            return False, "kinds must be a non-empty subset of: " + ", ".join(sorted(self.CUSTOM_KINDS))
        if parser in ("plaintext", "hashlist") and len(kinds) != 1:
            return False, f"{parser} feeds must declare exactly one kind"
        if parser == "hashlist" and kinds != ["hash"]:
            return False, "hashlist feeds must use kind 'hash'"
        sev = (spec.get("severity") or "medium").strip().lower()
        if sev not in self.SEV_RANK:
            return False, "severity must be low, medium, or high"
        collection = (spec.get("collection") or "").strip()
        if parser == "taxii21" and not collection:
            return False, "TAXII 2.1 feeds need a collection id"
        return True, {
            "name": name, "desc": (spec.get("desc") or "").strip()[:200],
            "kinds": kinds, "parser": parser, "severity": sev,
            "url": url, "collection": collection,
            "auth": bool(spec.get("auth")),
            "key_env": ((spec.get("key_env") or "").strip() or None),
            "mitre": (spec.get("mitre") or "").strip()[:20], "tos": None,
        }

    def _save_custom_feeds(self):
        try:
            arr = [{k: f.get(k) for k in ("id", "name", "desc", "kinds", "parser",
                                          "severity", "url", "collection", "auth",
                                          "key_env", "mitre", "on")}
                   for f in self.feeds.values() if f.get("custom")]
            tmp = self.custom_file + ".tmp"
            with open(tmp, "w") as fh:
                json.dump(arr, fh, indent=2)
            os.replace(tmp, self.custom_file)
        except OSError:
            pass

    def add_feed(self, spec):
        ok, res = self._validate_spec(spec)
        if not ok:
            return {"ok": False, "error": res}
        fid = self._make_id(res["name"])
        res["id"], res["custom"], res["on"] = fid, True, bool(spec.get("on", True))
        with self.lock:
            self.feeds[fid] = res
            self.state[fid] = {"count": 0, "last_fetched": None,
                               "last_error": None, "fetching": False}
        self._resolve_key(res)
        self._save_custom_feeds()
        if res["on"]:
            threading.Thread(target=self._fetch_one, args=(fid,), daemon=True).start()
        return {"ok": True, "id": fid, "status": self.status()}

    def update_feed(self, fid, spec):
        f = self.feeds.get(fid)
        if not f or not f.get("custom"):
            return {"ok": False, "error": "only custom feeds can be edited"}
        ok, res = self._validate_spec(spec)
        if not ok:
            return {"ok": False, "error": res}
        res["id"], res["custom"] = fid, True
        res["on"] = bool(spec.get("on", f.get("on", False)))
        with self.lock:
            self._purge_feed_nolock(fid)              # url/kinds may have changed → drop old hits
            self.state[fid]["count"] = 0
            self.feeds[fid] = res
        getattr(self, "_raw", {}).pop(fid, None)
        self._resolve_key(res)
        self._save_custom_feeds(); self._save_cache()
        if res["on"]:
            threading.Thread(target=self._fetch_one, args=(fid,), daemon=True).start()
        return {"ok": True, "status": self.status()}

    def remove_feed(self, fid):
        f = self.feeds.get(fid)
        if not f or not f.get("custom"):
            return {"ok": False, "error": "only custom feeds can be removed"}
        with self.lock:
            self._purge_feed_nolock(fid)
            self.feeds.pop(fid, None)
            self.state.pop(fid, None)
        getattr(self, "_raw", {}).pop(fid, None)
        try:
            self.secrets.delete(fid)
        except Exception:  # noqa: BLE001
            pass
        self._save_custom_feeds(); self._save_cache()
        return {"ok": True, "status": self.status()}

    def _resolve_key(self, f):
        """Populate f['api_key'] (in memory only) and f['key_source'] for an auth feed.
        Precedence: SecretStore (Keychain / 0600 file) > environment variable. The actual
        secret is never persisted to ioc-feeds.json nor exposed via status()."""
        if not f.get("auth"):
            f["api_key"], f["key_source"] = "", None
            return
        stored = self.secrets.get(f["id"])
        if stored:
            f["api_key"], f["key_source"] = stored, self.secrets.backend_for(f["id"])
            return
        env = os.environ.get(f.get("key_env", ""), "").strip() if f.get("key_env") else ""
        f["api_key"], f["key_source"] = (env, "env") if env else ("", None)

    def _save_config(self):
        try:
            out = {}
            for fid, f in self.feeds.items():
                if f.get("custom"):                       # custom feeds live in ioc-custom-feeds.json
                    continue
                rec = {"on": f["on"]}
                spec = next((s for s in IOC_FEED_CATALOG if s["id"] == fid), {})
                for k in ("url", "collection"):           # persist non-secret overrides
                    if f.get(k) and f.get(k) != spec.get(k):
                        rec[k] = f[k]
                out[fid] = rec                            # NB: api_key is never written here
            tmp = self.config_file + ".tmp"
            with open(tmp, "w") as fh:
                json.dump(out, fh, indent=2)
            os.replace(tmp, self.config_file)
        except OSError:
            pass

    # ---- on-disk cache of parsed indicators ----
    def _load_cache(self):
        try:
            with open(self.cache_file) as f:
                blob = json.load(f)
        except (OSError, ValueError):
            return
        for fid, rec in (blob.get("feeds") or {}).items():
            if fid not in self.feeds or not self.feeds[fid]["on"]:
                continue
            inds = rec.get("indicators") or {}
            self._install(fid, inds, persist=False)
            self.state[fid].update({"count": rec.get("count", 0),
                                    "last_fetched": rec.get("last_fetched")})
        # keep raw indicators around so we can re-save without re-fetching
        self._raw = {fid: (r.get("indicators") or {})
                     for fid, r in (blob.get("feeds") or {}).items()}

    def _save_cache(self):
        try:
            feeds = {}
            for fid in self.feeds:
                inds = getattr(self, "_raw", {}).get(fid)
                if inds:
                    feeds[fid] = {"indicators": inds, "count": self.state[fid]["count"],
                                  "last_fetched": self.state[fid]["last_fetched"]}
            tmp = self.cache_file + ".tmp"
            with open(tmp, "w") as fh:
                json.dump({"feeds": feeds}, fh)
            os.replace(tmp, self.cache_file)
        except OSError:
            pass

    # ---- indicator indexing ----
    def _install(self, fid, indicators, persist=True):
        """indicators = {"ip":[...], "hash":[...], "domain":[...], "url":[...],
        "cidr":[...]} of normalized values. Each becomes a hit tagged with the feed."""
        f = self.feeds[fid]
        hit_base = {"feed": fid, "name": f["name"], "severity": f["severity"],
                    "mitre": f.get("mitre"), "tos": f.get("tos")}
        with self.lock:
            self._purge_feed_nolock(fid)
            n = 0
            for kind in ("ip", "hash", "domain", "url"):
                for v in set(indicators.get(kind, [])):   # dedupe within this feed
                    if not v or (kind == "hash" and v in BENIGN_HASHES):
                        continue                            # drop empty-file & other benign hashes
                    hit = dict(hit_base)
                    self.idx[kind].setdefault(v, []).append(hit)
                    n += 1
            for cstr in indicators.get("cidr", []):
                try:
                    net = ipaddress.ip_network(cstr, strict=False)
                except ValueError:
                    continue
                self.cidr.append((net, dict(hit_base)))
                n += 1
            self.state[fid]["count"] = n
        if not hasattr(self, "_raw"):
            self._raw = {}
        self._raw[fid] = indicators
        if persist:
            self._save_cache()

    def _purge_feed_nolock(self, fid):
        for kind in self.idx:
            for v in list(self.idx[kind]):
                kept = [h for h in self.idx[kind][v] if h["feed"] != fid]
                if kept:
                    self.idx[kind][v] = kept
                else:
                    del self.idx[kind][v]
        self.cidr = [(n, h) for (n, h) in self.cidr if h["feed"] != fid]

    # ---- matching (called from build_graph) ----
    def match_hash(self, hashes):
        if not hashes:
            return []
        out, seen = [], set()
        with self.lock:
            for key in ("sha256", "sha1", "md5"):
                v = (hashes.get(key) or "").lower()
                if v in BENIGN_HASHES:
                    continue                               # an empty/benign file never "matches"
                for h in self.idx["hash"].get(v, []):
                    if h["feed"] not in seen:
                        seen.add(h["feed"])
                        out.append(h)
        return out

    def match_ip(self, ip):
        if not ip:
            return []
        out, seen = [], set()
        with self.lock:
            for h in self.idx["ip"].get(ip, []):
                if h["feed"] not in seen:
                    seen.add(h["feed"])
                    out.append(h)
            if self.cidr:
                try:
                    addr = ipaddress.ip_address(ip)
                    for net, h in self.cidr:
                        if h["feed"] not in seen and addr in net:
                            seen.add(h["feed"])
                            out.append(h)
                except ValueError:
                    pass
        return out

    def match_url(self, url):
        """Match a URL or its host against url + domain indicators."""
        if not url:
            return []
        host = host_from_url(url)
        out, seen = [], set()
        with self.lock:
            for h in self.idx["url"].get(url.lower(), []):
                if h["feed"] not in seen:
                    seen.add(h["feed"]); out.append(h)
            if host:
                for h in self.idx["domain"].get(host, []):
                    if h["feed"] not in seen:
                        seen.add(h["feed"]); out.append(h)
        return out

    # ---- status / control (API) ----
    def status(self):
        feeds = []
        with self.lock:
            for fid, f in self.feeds.items():
                st = self.state[fid]
                feeds.append({
                    "id": fid, "name": f["name"], "desc": f["desc"],
                    "kinds": f["kinds"], "parser": f["parser"], "severity": f["severity"],
                    "on": f["on"], "auth": bool(f.get("auth")),
                    "has_key": bool(f.get("api_key")) if f.get("auth") else None,
                    "key_source": f.get("key_source"),       # 'keychain'|'file'|'env'|None
                    "key_env": f.get("key_env"),
                    "key_editable": bool(f.get("auth")) and f.get("key_source") != "env",
                    "configured": bool(f.get("url")),
                    "count": st["count"], "last_fetched": st["last_fetched"],
                    "last_error": st["last_error"], "fetching": st["fetching"],
                    "tos": f.get("tos"),
                    "custom": bool(f.get("custom")),         # user-added (editable/removable)?
                    "url": f.get("url", "") if f.get("custom") else None,   # non-secret; for edit prefill
                    "collection": f.get("collection", "") if f.get("custom") else None,
                    "mitre": f.get("mitre", "") if f.get("custom") else None,
                })
        total = sum(self.state[fid]["count"] for fid in self.feeds if self.feeds[fid]["on"])
        return {"enabled": self.enabled, "interval": self.interval,
                "secret_backend": "keychain" if self.secrets.keychain else "file",
                "total_indicators": total, "feeds": feeds}

    def set_key(self, fid, key):
        """GUI entry point: store (or clear, if empty) a feed's API key in the SecretStore,
        re-resolve it, and re-fetch if the feed is on. Never echoes the key back."""
        if fid not in self.feeds or not self.feeds[fid].get("auth"):
            return {"ok": False, "error": "feed has no API key"}
        f = self.feeds[fid]
        if f.get("key_source") == "env":
            return {"ok": False, "error": f"key comes from ${f.get('key_env')} — unset the "
                                          f"environment variable to manage it here"}
        backend = self.secrets.set(fid, key)
        self._resolve_key(f)
        if f["on"] and f.get("api_key"):
            threading.Thread(target=self._fetch_one, args=(fid,), daemon=True).start()
        return {"ok": True, "stored": bool((key or "").strip()), "backend": backend}

    def set_enabled(self, fid, on):
        if fid not in self.feeds:
            return False
        self.feeds[fid]["on"] = bool(on)
        if self.feeds[fid].get("custom"):
            self._save_custom_feeds()
        else:
            self._save_config()
        if on:
            threading.Thread(target=self._fetch_one, args=(fid,), daemon=True).start()
        else:
            with self.lock:
                self._purge_feed_nolock(fid)
                self.state[fid]["count"] = 0
            getattr(self, "_raw", {}).pop(fid, None)
            self._save_cache()
        return True

    def refresh(self, fid=None):
        targets = [fid] if fid else [i for i, f in self.feeds.items() if f["on"]]
        for t in targets:
            threading.Thread(target=self._fetch_one, args=(t,), daemon=True).start()
        return len(targets)

    # ---- fetching ----
    def _refresh_loop(self):
        time.sleep(2)                                 # let the server come up first
        while True:
            for fid, f in list(self.feeds.items()):
                if not f["on"]:
                    continue
                st = self.state[fid]
                age = (time.time() - st["last_fetched"]) if st["last_fetched"] else 1e12
                if age >= self.interval:
                    self._fetch_one(fid)
                    time.sleep(1)                     # stagger publishers
            time.sleep(60)

    def _http_get(self, url, headers=None, timeout=30):
        req = urllib.request.Request(url, headers=headers or {
            "User-Agent": f"{USER_AGENT} (+local IOC matching)"})
        with urllib.request.urlopen(req, timeout=timeout) as r:
            return r.read().decode("utf-8", "replace")

    def _fetch_one(self, fid):
        f = self.feeds.get(fid)
        if not f or not f["on"]:
            return
        if not f.get("url"):
            self.state[fid]["last_error"] = "no URL configured"
            return
        if f.get("auth") and not f.get("api_key"):
            self.state[fid]["last_error"] = f"needs API key ({f.get('key_env','set api_key')})"
            return
        self.state[fid]["fetching"] = True
        try:
            inds = self._fetch_indicators(f)
            self._install(fid, inds)
            self.state[fid].update({"last_fetched": time.time(), "last_error": None})
        except Exception as e:  # noqa: BLE001
            self.state[fid]["last_error"] = str(e)[:200]
        finally:
            self.state[fid]["fetching"] = False

    def _fetch_indicators(self, f):
        parser = f["parser"]
        if parser == "taxii21":
            objs = self._fetch_taxii21(f["url"], f.get("collection", ""), f.get("api_key"))
            return parse_stix_objects(objs)
        headers = {"User-Agent": f"{USER_AGENT} (+local IOC matching)"}
        if f.get("api_key") and parser in ("stix_bundle", "hashlist", "plaintext"):
            headers["Authorization"] = f"Bearer {f['api_key']}"
        body = self._http_get(f["url"], headers=headers)
        if parser == "plaintext":
            return {"ip" if "ip" in f["kinds"] else f["kinds"][0]: parse_plaintext(body)}
        if parser == "cidr":
            return {"cidr": parse_plaintext(body)}
        if parser == "hashlist":
            return {"hash": parse_hashlist(body)}
        if parser == "threatfox_csv":
            return parse_threatfox_csv(body)
        if parser == "urlhaus_csv":
            return parse_urlhaus_csv(body)
        if parser == "stix_bundle":
            return parse_stix_objects((json.loads(body) or {}).get("objects", []))
        raise ValueError(f"unknown parser {parser}")

    def _fetch_taxii21(self, root, collection, key):
        """Minimal TAXII 2.1 client: GET the collection's objects envelope. `root`
        should be the API-root URL; `collection` the collection id."""
        if not collection:
            raise ValueError("TAXII collection id not set")
        base = root.rstrip("/")
        url = f"{base}/collections/{collection}/objects/"
        headers = {"Accept": "application/taxii+json;version=2.1",
                   "User-Agent": USER_AGENT}
        if key:
            headers["Authorization"] = f"Bearer {key}"
        objs, pages = [], 0
        while url and pages < 20:
            body = self._http_get(url, headers=headers, timeout=45)
            env = json.loads(body) or {}
            objs.extend(env.get("objects", []))
            nxt = env.get("next")
            url = f"{base}/collections/{collection}/objects/?next={nxt}" if (env.get("more") and nxt) else None
            pages += 1
        return objs


# ---- feed body parsers (module-level so they're independently unit-testable) ----
def parse_plaintext(body):
    out = []
    for line in body.splitlines():
        line = line.strip()
        if not line or line[0] in "#;":
            continue
        out.append(line.split()[0].split(",")[0].strip().lower())
    return [v for v in out if v]


def parse_hashlist(body):
    return sorted({m.group(1).lower() for m in IOC_HASH_RE.finditer(body)})


def _split_csv_line(line):
    """abuse.ch CSVs are quote-wrapped, comma-separated; tolerate the csv module."""
    import csv
    try:
        return next(csv.reader([line], skipinitialspace=True))
    except StopIteration:
        return []


def parse_threatfox_csv(body):
    """Cols: first_seen, id, ioc, ioc_type, threat_type, malware, ?, malware_printable,
    ?, confidence, ... ioc_type in {ip:port, domain, url, md5_hash, sha256_hash, ...}."""
    out = {"ip": [], "domain": [], "url": [], "hash": []}
    for line in body.splitlines():
        if not line or line.lstrip()[:1] in "#":
            continue
        cols = _split_csv_line(line)
        if len(cols) < 4:
            continue
        ioc, itype = cols[2].strip(), cols[3].strip().lower()
        if not ioc:
            continue
        if itype.startswith("ip"):
            out["ip"].append(ioc.split(":")[0].lower())
        elif itype == "domain":
            out["domain"].append(ioc.lower())
        elif itype == "url":
            out["url"].append(ioc.lower())
            h = host_from_url(ioc)
            if h:
                out["domain"].append(h)
        elif "hash" in itype:
            out["hash"].append(ioc.lower())
    return out


def parse_urlhaus_csv(body):
    """Cols: id, dateadded, url, url_status, last_online, threat, tags, link, reporter."""
    out = {"url": [], "domain": []}
    for line in body.splitlines():
        if not line or line.lstrip()[:1] in "#":
            continue
        cols = _split_csv_line(line)
        if len(cols) < 3:
            continue
        url = cols[2].strip()
        if not url:
            continue
        out["url"].append(url.lower())
        h = host_from_url(url)
        if h and not _looks_like_ip(h):
            out["domain"].append(h)
    return out


def _looks_like_ip(s):
    try:
        ipaddress.ip_address(s)
        return True
    except ValueError:
        return False


# STIX pattern matchers, e.g. [file:hashes.'SHA-256' = '...'] / [ipv4-addr:value = '...']
_STIX_HASH = re.compile(r"file:hashes\.'?[\w-]+'?\s*=\s*'([^']+)'", re.I)
_STIX_IP = re.compile(r"ipv[46]-addr:value\s*=\s*'([^']+)'", re.I)
_STIX_DOMAIN = re.compile(r"domain-name:value\s*=\s*'([^']+)'", re.I)
_STIX_URL = re.compile(r"\burl:value\s*=\s*'([^']+)'", re.I)


def parse_stix_objects(objects):
    """Extract indicators from a list of STIX 2.x SDOs (bundle.objects or a TAXII
    envelope's objects). Reads the `pattern` of each `indicator`."""
    out = {"ip": [], "hash": [], "domain": [], "url": []}
    for o in objects or []:
        if not isinstance(o, dict):
            continue
        # indicator SDO with a STIX pattern
        if o.get("type") == "indicator":
            pat = o.get("pattern") or ""
            for m in _STIX_HASH.finditer(pat):
                out["hash"].append(m.group(1).lower())
            for m in _STIX_IP.finditer(pat):
                out["ip"].append(m.group(1).split("/")[0].lower())
            for m in _STIX_DOMAIN.finditer(pat):
                out["domain"].append(m.group(1).lower())
            for m in _STIX_URL.finditer(pat):
                out["url"].append(m.group(1).lower())
        # also harvest standalone Cyber-observable objects (some feeds ship these)
        elif o.get("type") == "file":
            for v in (o.get("hashes") or {}).values():
                if isinstance(v, str):
                    out["hash"].append(v.lower())
        elif o.get("type") in ("ipv4-addr", "ipv6-addr") and o.get("value"):
            out["ip"].append(str(o["value"]).split("/")[0].lower())
        elif o.get("type") == "domain-name" and o.get("value"):
            out["domain"].append(str(o["value"]).lower())
        elif o.get("type") == "url" and o.get("value"):
            out["url"].append(str(o["value"]).lower())
    return {k: sorted(set(v)) for k, v in out.items()}


def ioc_is_confident(hits):
    """True if any match comes from a medium/high-severity feed — i.e. a real malware
    indicator, not mere reputation/anonymizer noise (Tor, low-rep IP lists). Used to
    skip a rate-limited, data-leaking VirusTotal lookup when a local feed already has a
    confident verdict. Low-severity-only hits still fall through to VT for enrichment."""
    return any(h.get("severity") in ("medium", "high") for h in (hits or []))


def apply_ioc_severity(score, reasons, hits):
    """Fold local threat-intel matches into a node's score/reasons. Mirrors
    apply_vt_severity but uses pre-fetched feed indicators (no network call)."""
    if not hits:
        return score
    best = max(hits, key=lambda h: IOCFeeds.SEV_RANK.get(h["severity"], 0))
    names = ", ".join(sorted({h["name"] for h in hits}))
    floor = IOC_SEVERITY_FLOOR.get(best["severity"], 25)
    reasons.append(reason(
        f"Threat-intel match — listed on {names}", best.get("mitre"), 0))
    return max(score, floor)


class GeoIP:
    """Offline IP geolocation / ASN enrichment from an ipinfo.io database.

    Mirrors the IOCFeeds privacy model: we download a snapshot of the whole database
    once (refreshed on a timer) and then resolve every IP **locally** with an in-memory
    range index — so looking up which hosts the machine talks to NEVER leaks those IPs
    to ipinfo (unlike their live API or VirusTotal's IP endpoint). Only the periodic
    database download itself touches ipinfo.

    Two tiers:
      • free  — ipinfo's free Country+ASN CSV (country, continent, ASN, AS name/domain).
                Needs a free signup token; CC BY-SA attribution.
      • paid  — any richer ipinfo CSV the operator subscribes to (adds city/region/
                lat-lng/precise org). Same plumbing; just point it at the paid dataset.

    The CSV is parsed generically off its header row, so either tier — or any ipinfo
    CSV with start_ip/end_ip (or a CIDR/range column) — loads without code changes."""

    # Default dataset URLs per tier (token appended as ?token=). Overridable in
    # geoip-settings.json so a different ipinfo product slug can be pointed at.
    DEFAULT_URLS = {
        "free": "https://ipinfo.io/data/free/country_asn.csv.gz",
        "paid": "https://ipinfo.io/data/standard_location.csv.gz",
    }
    SECRET_ID = "geoip"                 # SecretStore account for the ipinfo token
    # CSV header -> normalized field. First match wins; unknown columns ignored.
    FIELD_ALIASES = {
        "country": "country", "country_code": "country",
        "country_name": "country_name",
        "continent": "continent", "continent_name": "continent_name",
        "asn": "asn", "as_number": "asn",
        "as_name": "as_name", "asname": "as_name", "as_org": "as_name", "org": "as_name",
        "as_domain": "as_domain", "domain": "as_domain",
        "city": "city", "region": "region", "postal": "postal",
        "timezone": "timezone", "lat": "lat", "latitude": "lat",
        "lng": "lng", "long": "lng", "longitude": "lng",
    }

    def __init__(self, enabled=True, interval=86400, tier="free",
                 settings_file=None, cache_file=None, secrets=None):
        self.enabled = enabled
        self.interval = max(3600, interval)            # at most hourly; the DB updates daily
        self.tier = tier if tier in self.DEFAULT_URLS else "free"
        self.settings_file = settings_file or os.path.join(HERE, "geoip-settings.json")
        self.cache_file = cache_file or os.path.join(HERE, "geoip-db.csv.gz")
        self.secrets = secrets or SecretStore()
        self.urls = dict(self.DEFAULT_URLS)
        self.lock = threading.Lock()
        # Per IP version: parallel arrays sorted by start int + record dicts. bisect on starts.
        self._idx = {4: {"starts": [], "ends": [], "recs": []},
                     6: {"starts": [], "ends": [], "recs": []}}
        self.state = {"rows": 0, "last_fetched": None, "last_error": None,
                      "fetching": False, "loaded_tier": None}
        self._load_settings()
        self._load_cache()
        if self.enabled:
            threading.Thread(target=self._refresh_loop, daemon=True).start()

    # ---- token (reuses the Keychain-backed SecretStore) ----
    def has_token(self):
        return bool(self.secrets.get(self.SECRET_ID))

    def token_source(self):
        return self.secrets.backend_for(self.SECRET_ID) if self.has_token() else None

    def set_token(self, token):
        backend = self.secrets.set(self.SECRET_ID, token)
        if (token or "").strip() and self.enabled:
            threading.Thread(target=self._fetch, daemon=True).start()
        return {"ok": True, "stored": bool((token or "").strip()), "backend": backend}

    # ---- settings ----
    def _load_settings(self):
        try:
            with open(self.settings_file) as f:
                d = json.load(f) or {}
        except (OSError, ValueError):
            return
        if d.get("tier") in self.DEFAULT_URLS:
            self.tier = d["tier"]
        if isinstance(d.get("urls"), dict):
            for k in ("free", "paid"):
                if d["urls"].get(k):
                    self.urls[k] = d["urls"][k]

    def _save_settings(self):
        try:
            urls = {k: v for k, v in self.urls.items() if v != self.DEFAULT_URLS.get(k)}
            tmp = self.settings_file + ".tmp"
            with open(tmp, "w") as f:
                json.dump({"tier": self.tier, "urls": urls}, f, indent=2)
            os.replace(tmp, self.settings_file)
        except OSError:
            pass

    def set_tier(self, tier):
        if tier not in self.DEFAULT_URLS:
            return {"ok": False, "error": "tier must be 'free' or 'paid'"}
        self.tier = tier
        self._save_settings()
        if self.enabled and self.has_token():       # different dataset -> re-download
            threading.Thread(target=self._fetch, daemon=True).start()
        return {"ok": True, "status": self.status()}

    def set_enabled(self, on):
        self.enabled = bool(on)
        if self.enabled:
            threading.Thread(target=self._fetch, daemon=True).start()
        return {"ok": True, "status": self.status()}

    def refresh(self):
        if not self.enabled:
            return {"ok": False, "error": "geo enrichment is off"}
        threading.Thread(target=self._fetch, daemon=True).start()
        return {"ok": True, "refreshing": True}

    # ---- disk cache (the .gz itself; parse on launch for an offline warm start) ----
    def _load_cache(self):
        if not os.path.exists(self.cache_file):
            return
        try:
            with open(self.cache_file, "rb") as f:
                self._parse_and_index(f.read())
            self.state["last_fetched"] = os.path.getmtime(self.cache_file)
            self.state["loaded_tier"] = self.tier
        except Exception as e:  # noqa: BLE001
            self.state["last_error"] = f"cache parse: {str(e)[:160]}"

    # ---- fetch ----
    def _refresh_loop(self):
        time.sleep(3)                                  # let the server come up first
        while True:
            if self.enabled and self.has_token():
                age = (time.time() - self.state["last_fetched"]) if self.state["last_fetched"] else 1e12
                if age >= self.interval or self.state["loaded_tier"] != self.tier:
                    self._fetch()
            time.sleep(300)

    def _url_for_tier(self):
        return self.urls.get(self.tier) or self.DEFAULT_URLS["free"]

    def _fetch(self):
        if not self.enabled:
            return
        token = self.secrets.get(self.SECRET_ID)
        if not token:
            self.state["last_error"] = "no ipinfo token — add one to download the database"
            return
        if self.state["fetching"]:
            return
        self.state["fetching"] = True
        try:
            url = self._url_for_tier()
            sep = "&" if "?" in url else "?"
            req = urllib.request.Request(
                url + f"{sep}token={urllib.parse.quote(token)}",
                headers={"User-Agent": f"{USER_AGENT} (+offline IP enrichment)"})
            with urllib.request.urlopen(req, timeout=120) as r:
                raw = r.read()
            self._parse_and_index(raw)
            try:                                       # persist the .gz for an offline warm start
                tmp = self.cache_file + ".tmp"
                with open(tmp, "wb") as f:
                    f.write(raw)
                os.replace(tmp, self.cache_file)
            except OSError:
                pass
            self.state.update({"last_fetched": time.time(), "last_error": None,
                               "loaded_tier": self.tier})
        except Exception as e:  # noqa: BLE001
            self.state["last_error"] = str(e)[:200]
        finally:
            self.state["fetching"] = False

    def _parse_and_index(self, raw_gz):
        """Parse an ipinfo CSV(.gz) into per-version sorted range arrays."""
        data = gzip.decompress(raw_gz) if raw_gz[:2] == b"\x1f\x8b" else raw_gz
        text = io.StringIO(data.decode("utf-8", "replace"))
        reader = csv.reader(text)
        try:
            header = next(reader)
        except StopIteration:
            return
        cols = [(h or "").strip().lower() for h in header]
        # locate range columns
        def col(*names):
            for nm in names:
                if nm in cols:
                    return cols.index(nm)
            return None
        ci_start = col("start_ip", "start", "range_start", "ip_range_start")
        ci_end = col("end_ip", "end", "range_end", "ip_range_end")
        ci_cidr = col("network", "range", "cidr", "ip_range")
        # data columns -> normalized field
        data_cols = {}
        for i, c in enumerate(cols):
            if c in self.FIELD_ALIASES and i not in (ci_start, ci_end, ci_cidr):
                data_cols.setdefault(self.FIELD_ALIASES[c], i)
        tmp = {4: [], 6: []}                            # version -> [(start_int, end_int, rec)]
        for row in reader:
            if not row:
                continue
            try:
                if ci_start is not None and ci_end is not None:
                    sa = ipaddress.ip_address(row[ci_start].strip())
                    ea = ipaddress.ip_address(row[ci_end].strip())
                    start_i, end_i, ver = int(sa), int(ea), sa.version
                elif ci_cidr is not None:
                    net = ipaddress.ip_network(row[ci_cidr].strip(), strict=False)
                    start_i, end_i, ver = int(net.network_address), int(net.broadcast_address), net.version
                else:
                    return                              # no usable range columns
            except (ValueError, IndexError):
                continue
            rec = {}
            for field, idx in data_cols.items():
                if idx < len(row):
                    v = (row[idx] or "").strip()
                    if v:
                        rec[field] = v
            tmp[ver].append((start_i, end_i, rec))
        idx = {4: {"starts": [], "ends": [], "recs": []},
               6: {"starts": [], "ends": [], "recs": []}}
        total = 0
        for ver in (4, 6):
            tmp[ver].sort(key=lambda t: t[0])
            idx[ver]["starts"] = [t[0] for t in tmp[ver]]
            idx[ver]["ends"] = [t[1] for t in tmp[ver]]
            idx[ver]["recs"] = [t[2] for t in tmp[ver]]
            total += len(tmp[ver])
        with self.lock:
            self._idx = idx
            self.state["rows"] = total

    # ---- lookup (called from build_graph; purely local, no network) ----
    def lookup(self, ip):
        if not self.enabled or not ip:
            return None
        try:
            addr = ipaddress.ip_address(ip)
        except ValueError:
            return None
        n = int(addr)
        with self.lock:
            v = self._idx.get(addr.version)
            if not v or not v["starts"]:
                return None
            j = bisect.bisect_right(v["starts"], n) - 1
            if j < 0 or n > v["ends"][j]:
                return None
            rec = v["recs"][j]
        if not rec:
            return None
        out = dict(rec)
        cc = (out.get("country") or "").upper()
        if cc and len(cc) == 2:
            out["country"] = cc
        out["summary"] = self._summary(out)
        return out

    @staticmethod
    def _summary(rec):
        bits = []
        loc = " ".join(x for x in (rec.get("city"), rec.get("region")) if x)
        place = ", ".join(x for x in (loc, rec.get("country_name") or rec.get("country")) if x)
        if place:
            bits.append(place)
        if rec.get("asn") or rec.get("as_name"):
            asn = rec.get("asn") or ""
            if asn and not str(asn).upper().startswith("AS"):
                asn = "AS" + str(asn)
            bits.append(" ".join(x for x in (asn, rec.get("as_name")) if x))
        return " · ".join(bits)

    def status(self):
        return {
            "enabled": self.enabled, "tier": self.tier, "interval": self.interval,
            "rows": self.state["rows"], "last_fetched": self.state["last_fetched"],
            "last_error": self.state["last_error"], "fetching": self.state["fetching"],
            "has_token": self.has_token(), "token_source": self.token_source(),
            "secret_backend": "keychain" if self.secrets.keychain else "file",
            "url": self._url_for_tier(),
        }


# ===========================================================================
# In-agent vulnerability scanning (CTEM-Lite), Linux (Debian/Ubuntu-first).
#
# Three cooperating pieces, all pure-stdlib and entirely local:
#   * LinuxOSCurrency    — distro/kernel + pending APT updates (security pocket
#                          flagged) + reboot-required. The authoritative "are you
#                          patched" signal: a distro security update exists
#                          precisely when a CVE has a fix available.
#   * LinuxSoftwareInventory — installed dpkg packages + pip/npm globals.
#   * VulnFeed / OSVFeeds — shared with the macOS agent: a JSON advisory feed
#                          (matched against dpkg packages) and offline OSV
#                          language-ecosystem matching. Only feeds are fetched;
#                          nothing about the inventory leaves the machine.
#
# VulnScanner ties them into prioritized findings served on /api/vulns. A dpkg
# finding is flagged "live" when a running process is owned by that package
# (resolved through the agent's DpkgIndex). The scan runs on a long timer.
# ===========================================================================


def _ver_key(v):
    """Numeric version comparison key: the integer runs in a dotted version.

    Good for the dotted-decimal versions that .app bundles and Homebrew report
    (e.g. '131.0.6778.69', '3.4.0'). Ecosystem-specific semantics (PEP 440,
    semver pre-releases) are a deliberate follow-on handled per-feed."""
    parts = re.findall(r"\d+", str(v or ""))
    return tuple(int(p) for p in parts) if parts else ()


def _vcmp_key(a, b):
    """Compare two _ver_key tuples; shorter is zero-padded. Returns -1/0/1."""
    n = max(len(a), len(b))
    a = a + (0,) * (n - len(a))
    b = b + (0,) * (n - len(b))
    return (a > b) - (a < b)


def _version_affected(version, affected):
    """Does `version` fall inside any constraint-set in `affected`?

    `affected` is a list of dicts (OR across the list). Each dict is a set of
    bound operators (lt/le/gt/ge/eq) that must ALL hold (AND within the set).
    An unparseable version matches nothing — we never raise a finding we cannot
    stand behind."""
    vk = _ver_key(version)
    if not vk or not affected:
        return False
    for cs in affected:
        if not isinstance(cs, dict) or not cs:
            continue
        ok = True
        for op, bound in cs.items():
            c = _vcmp_key(vk, _ver_key(bound))
            if ((op == "lt" and not c < 0) or (op == "le" and not c <= 0)
                    or (op == "gt" and not c > 0) or (op == "ge" and not c >= 0)
                    or (op == "eq" and c != 0)):
                ok = False
                break
        if ok:
            return True
    return False


def _run_as_user(cmd, timeout=60):
    """run() an inventory command. On Linux the system package tools (pip/npm) list the
    system/global view fine as root, so unlike macOS Homebrew there's no user to drop to."""
    return run(cmd, timeout=timeout)


def _pip_packages():
    """Globally-installed Python distributions, tagged with the OSV 'PyPI' ecosystem."""
    py = shutil.which("python3") or shutil.which("python")
    if not py:
        return []
    rc, out, _ = _run_as_user([py, "-m", "pip", "list", "--format=json",
                               "--disable-pip-version-check"], timeout=60)
    if rc != 0:
        return []
    try:
        rows = json.loads(out)
    except ValueError:
        return []
    return [{"ecosystem": "PyPI", "name": r["name"], "version": r.get("version")}
            for r in rows if isinstance(r, dict) and r.get("name")]


def _npm_global_packages():
    """Globally-installed npm packages, tagged with the OSV 'npm' ecosystem."""
    if not shutil.which("npm"):
        return []
    rc, out, _ = _run_as_user(["npm", "ls", "-g", "--depth=0", "--json"], timeout=60)
    if not out:
        return []
    try:
        deps = (json.loads(out) or {}).get("dependencies") or {}
    except ValueError:
        return []
    return [{"ecosystem": "npm", "name": n, "version": (d or {}).get("version")}
            for n, d in deps.items() if n]


# ---- OSV advisory parsing (used by OSVFeeds to match language packages offline) ----
def _osv_cve(rec):
    for a in rec.get("aliases") or []:
        if str(a).upper().startswith("CVE-"):
            return a
    return rec.get("id")


def _osv_severity(rec):
    ds = rec.get("database_specific") or {}
    s = str(ds.get("severity") or "").lower()
    if s in ("critical", "high", "medium", "low"):
        return s
    if s == "moderate":
        return "medium"
    for sev in rec.get("severity") or []:
        try:
            n = float(sev.get("score"))
        except (TypeError, ValueError):
            continue
        return "critical" if n >= 9 else "high" if n >= 7 else "medium" if n >= 4 else "low"
    return "medium"


def _osv_url(rec):
    for ref in rec.get("references") or []:
        if isinstance(ref, dict) and ref.get("url"):
            return ref["url"]
    return "https://osv.dev/vulnerability/%s" % rec.get("id", "")


def _osv_cvss(rec):
    """A human CVSS string (score or vector) from an OSV record's severity block, or None."""
    for sev in rec.get("severity") or []:
        if isinstance(sev, dict) and sev.get("score"):
            t = sev.get("type") or "CVSS"
            return "%s %s" % (t.replace("_", ""), sev["score"])
    ds = rec.get("database_specific") or {}
    return str(ds.get("cvss")) if ds.get("cvss") else None


def _finding_sig(f):
    """Stable key for a finding across scans/versions: kind + component (no version) + advisory id.
    Used to persist a remediation decision so it follows the finding even as the version changes."""
    return "%s|%s|%s" % ((f.get("kind") or ""), (f.get("component") or "").lower(),
                         (f.get("cve") or f.get("id") or f.get("title") or "").lower())


def _osv_affected(version, affected_entries):
    """OSV match: is `version` affected by any of this package's affected entries? Returns the
    fixed version (str, possibly '') when affected, else None. Handles the exact `versions` list
    and SEMVER/ECOSYSTEM ranges (introduced/fixed/last_affected); GIT ranges are skipped."""
    vk = _ver_key(version)
    if not vk:
        return None
    for aff in affected_entries or []:
        if any(_vcmp_key(vk, _ver_key(x)) == 0 for x in (aff.get("versions") or [])):
            return _osv_fixed(aff) or ""
        for rng in aff.get("ranges") or []:
            if rng.get("type") not in ("SEMVER", "ECOSYSTEM"):
                continue
            introduced = fixed = last = None
            for ev in rng.get("events") or []:
                if "introduced" in ev:
                    introduced = ev["introduced"]
                elif "fixed" in ev:
                    fixed = ev["fixed"]
                elif "last_affected" in ev:
                    last = ev["last_affected"]
            lo_ok = True if (not introduced or introduced == "0") else _vcmp_key(vk, _ver_key(introduced)) >= 0
            if fixed is not None:
                hi_ok = _vcmp_key(vk, _ver_key(fixed)) < 0
            elif last is not None:
                hi_ok = _vcmp_key(vk, _ver_key(last)) <= 0
            else:
                hi_ok = True
            if lo_ok and hi_ok:
                return fixed or ""
    return None


def _osv_fixed(aff):
    for rng in aff.get("ranges") or []:
        for ev in rng.get("events") or []:
            if ev.get("fixed"):
                return ev["fixed"]
    return None


# A small, deliberately EXAMPLE advisory set. It proves the match pipeline offline
# (one per match kind: a bundle id, another bundle id, a Homebrew package) and is
# flagged example:true end-to-end so a finding is never passed off as a confirmed,

class VulnFeed:
    """GeoIP-style vulnerability advisory feed: fetch once on a timer, index, match
    locally. Seed advisories are always present; a downloaded feed layers on top."""

    def __init__(self, enabled=True, interval=86400, url=None,
                 cache_file=None, seed=None):
        self.enabled = enabled
        self.interval = max(3600, interval)
        self.url = (url or "").strip() or None
        self.cache_file = cache_file or os.path.join(HERE, "vuln-feed.json")
        self.seed = list(seed if seed is not None else VULN_SEED_ADVISORIES)
        self._remote = []
        self.lock = threading.Lock()
        self._idx = {"bundle_id": {}, "name": {}, "eco": {}}
        self.state = {"advisories": 0, "last_fetched": None, "last_error": None,
                      "fetching": False, "source": "seed"}
        self._reindex()
        self._load_cache()
        if self.enabled and self.url:
            threading.Thread(target=self._refresh_loop, daemon=True).start()

    @staticmethod
    def _keys_for(adv):
        m = adv.get("match") or {}
        out = []
        if m.get("bundle_id"):
            out.append(("bundle_id", str(m["bundle_id"]).lower()))
        if m.get("name"):
            out.append(("name", str(m["name"]).lower()))
        if m.get("ecosystem") and m.get("package"):
            out.append(("eco", "%s::%s" % (str(m["ecosystem"]).lower(),
                                           str(m["package"]).lower())))
        return out

    def _reindex(self):
        idx = {"bundle_id": {}, "name": {}, "eco": {}}
        n = 0
        for adv in self.seed + self._remote:
            if not isinstance(adv, dict) or not adv.get("affected"):
                continue
            keys = self._keys_for(adv)
            if not keys:
                continue
            for kind, key in keys:
                idx[kind].setdefault(key, []).append(adv)
            n += 1
        with self.lock:
            self._idx = idx
            self.state["advisories"] = n

    def match(self, bundle_id=None, name=None, version=None,
              ecosystem=None, package=None):
        with self.lock:
            idx = self._idx
        cand, seen = [], set()
        for kind, key in (("bundle_id", bundle_id and bundle_id.lower()),
                          ("name", name and name.lower()),
                          ("eco", (ecosystem and package)
                           and "%s::%s" % (ecosystem.lower(), package.lower()))):
            if not key:
                continue
            for adv in idx[kind].get(key, []):
                if id(adv) not in seen:
                    seen.add(id(adv))
                    cand.append(adv)
        return [adv for adv in cand if _version_affected(version, adv.get("affected"))]

    # ---- fetch (mirrors GeoIP/IOCFeeds: one outbound download, then local match) ----
    def _refresh_loop(self):
        time.sleep(4)
        while True:
            if self.enabled and self.url:
                age = ((time.time() - self.state["last_fetched"])
                       if self.state["last_fetched"] else 1e12)
                if age >= self.interval:
                    self._fetch()
            time.sleep(300)

    def _load_cache(self):
        try:
            with open(self.cache_file) as f:
                self._ingest(json.load(f), source="cache")
            self.state["last_fetched"] = os.path.getmtime(self.cache_file)
        except (OSError, ValueError):
            pass

    def _fetch(self):
        if not (self.enabled and self.url) or self.state["fetching"]:
            return
        self.state["fetching"] = True
        try:
            req = urllib.request.Request(
                self.url, headers={"User-Agent": "%s (+offline vuln feed)" % USER_AGENT})
            with urllib.request.urlopen(req, timeout=120) as r:
                raw = r.read()
            data = json.loads(gzip.decompress(raw) if raw[:2] == b"\x1f\x8b" else raw)
            self._ingest(data, source="remote")
            try:
                tmp = self.cache_file + ".tmp"
                with open(tmp, "w") as f:
                    json.dump(data, f)
                os.replace(tmp, self.cache_file)
            except OSError:
                pass
            self.state.update({"last_fetched": time.time(), "last_error": None})
        except Exception as e:  # noqa: BLE001
            self.state["last_error"] = str(e)[:200]
        finally:
            self.state["fetching"] = False

    def _ingest(self, data, source):
        advs = data.get("advisories") if isinstance(data, dict) else data
        if not isinstance(advs, list):
            return
        self._remote = [a for a in advs if isinstance(a, dict) and a.get("match")]
        self.state["source"] = source
        self._reindex()

    def refresh(self):
        if not (self.enabled and self.url):
            return {"ok": False, "error": "no feed url configured (seed only)"}
        threading.Thread(target=self._fetch, daemon=True).start()
        return {"ok": True, "refreshing": True}

    def status(self):
        return {"enabled": self.enabled, "url": self.url, "interval": self.interval,
                "advisories": self.state["advisories"], "source": self.state["source"],
                "seed": len(self.seed), "remote": len(self._remote),
                "last_fetched": self.state["last_fetched"],
                "last_error": self.state["last_error"]}


OSV_ECOSYSTEMS = {"pypi": "PyPI", "npm": "npm"}      # our key -> OSV ecosystem name
OSV_URL = "https://osv-vulnerabilities.storage.googleapis.com/%s/all.zip"


class OSVFeeds:
    """Offline OSV matching for language packages. Downloads the per-ecosystem advisory archive
    (all.zip) on a daily cadence — the one outbound fetch, exactly like GeoIP — then indexes and
    matches installed versions LOCALLY. Nothing about the inventory leaves the machine.

    The index is filtered to the packages actually installed (set each scan via prepare()), so a
    host holds advisories only for its own software, not the entire ecosystem. In 'auto' mode an
    ecosystem is downloaded only once a package for it is present."""

    def __init__(self, enabled=True, interval=86400, ecosystems="auto", cache_dir=None):
        self.enabled = enabled
        self.interval = max(3600, interval)
        self.mode = (ecosystems or "auto")           # "auto" | "off" | "pypi,npm"
        self.cache_dir = cache_dir or HERE
        self.lock = threading.Lock()
        self._idx = {}          # osv_eco -> {pkg_lower -> [compact_record, ...]}
        self.wanted = {}        # osv_eco -> set(pkg_lower)
        self.state = {}         # osv_eco -> {records, last_fetched, last_error, fetching}

    def _wants(self, key):
        if self.mode == "off":
            return False
        if self.mode == "auto":
            return True
        return key in {m.strip().lower() for m in self.mode.split(",") if m.strip()}

    def _zip_path(self, key):
        return os.path.join(self.cache_dir, "osv-%s.zip" % key)

    def prepare(self, packages):
        """Point the index at the currently-installed packages, fetching/indexing each active
        ecosystem as needed. Called from the scanner's daily scan (blocking, bounded)."""
        if not self.enabled or self.mode == "off":
            return
        want = {}
        for p in packages or []:
            key = _OSV_KEY_BY_NAME.get(p.get("ecosystem"))
            if key and self._wants(key):
                want.setdefault(OSV_ECOSYSTEMS[key], set()).add(str(p.get("name") or "").lower())
        with self.lock:
            self.wanted = want
        for key, osv_eco in OSV_ECOSYSTEMS.items():
            if osv_eco in want and want[osv_eco]:
                self._ensure(key, osv_eco)
            else:
                with self.lock:
                    self._idx.pop(osv_eco, None)

    def _ensure(self, key, osv_eco):
        st = self.state.setdefault(osv_eco, {"records": 0, "last_fetched": None,
                                             "last_error": None, "fetching": False})
        zp = self._zip_path(key)
        fresh = os.path.exists(zp) and (time.time() - os.path.getmtime(zp)) < self.interval
        if not fresh:
            self._fetch(key, osv_eco)
        if os.path.exists(zp):
            self._index(key, osv_eco)

    def _fetch(self, key, osv_eco):
        st = self.state[osv_eco]
        if st["fetching"]:
            return
        st["fetching"] = True
        try:
            req = urllib.request.Request(OSV_URL % osv_eco,
                                         headers={"User-Agent": "%s (+offline OSV)" % USER_AGENT})
            with urllib.request.urlopen(req, timeout=180) as r:
                raw = r.read()
            tmp = self._zip_path(key) + ".tmp"
            with open(tmp, "wb") as f:
                f.write(raw)
            os.replace(tmp, self._zip_path(key))
            st["last_fetched"] = time.time()
            st["last_error"] = None
        except Exception as e:  # noqa: BLE001
            st["last_error"] = str(e)[:200]
        finally:
            st["fetching"] = False

    def _index(self, key, osv_eco):
        with self.lock:
            wanted = set(self.wanted.get(osv_eco) or ())
        if not wanted:
            return
        idx = {}
        try:
            with zipfile.ZipFile(self._zip_path(key)) as z:
                for name in z.namelist():
                    if not name.endswith(".json"):
                        continue
                    try:
                        rec = json.loads(z.read(name))
                    except (ValueError, OSError):
                        continue
                    self._index_record(rec, osv_eco, wanted, idx)
        except (zipfile.BadZipFile, OSError) as e:
            self.state.setdefault(osv_eco, {})["last_error"] = "index: %s" % str(e)[:160]
            return
        with self.lock:
            self._idx[osv_eco] = idx
            self.state.setdefault(osv_eco, {})["records"] = sum(len(v) for v in idx.values())

    @staticmethod
    def _index_record(rec, osv_eco, wanted, idx):
        if rec.get("withdrawn"):
            return
        per_pkg = {}
        for aff in rec.get("affected") or []:
            pkg = (aff.get("package") or {})
            if pkg.get("ecosystem") != osv_eco:
                continue
            pname = str(pkg.get("name") or "").lower()
            if pname in wanted:
                per_pkg.setdefault(pname, []).append(aff)
        if not per_pkg:
            return
        compact = {"id": rec.get("id"), "cve": _osv_cve(rec), "severity": _osv_severity(rec),
                   "title": rec.get("summary") or (rec.get("details") or "")[:120],
                   "description": (rec.get("details") or rec.get("summary") or "")[:1500],
                   "references": [r["url"] for r in (rec.get("references") or [])
                                  if isinstance(r, dict) and r.get("url")][:8],
                   "cvss": _osv_cvss(rec),
                   "aliases": [str(a) for a in (rec.get("aliases") or [])][:8],
                   "published": rec.get("published") or rec.get("modified"),
                   "url": _osv_url(rec)}
        for pname, affs in per_pkg.items():
            idx.setdefault(pname, []).append(dict(compact, affected=affs))

    def match(self, ecosystem, name, version):
        """Advisories affecting (ecosystem, name, version), in the scanner's advisory format."""
        with self.lock:
            bucket = (self._idx.get(ecosystem) or {}).get(str(name or "").lower())
            recs = list(bucket) if bucket else []
        hits = []
        for rec in recs:
            fixed = _osv_affected(version, rec.get("affected"))
            if fixed is None:
                continue
            hits.append({"id": rec["id"], "cve": rec["cve"], "severity": rec["severity"],
                         "title": rec["title"], "url": rec["url"], "fixed": fixed or None,
                         "description": rec.get("description"), "references": rec.get("references"),
                         "cvss": rec.get("cvss"), "aliases": rec.get("aliases"),
                         "published": rec.get("published"), "example": False})
        return hits

    def status(self):
        with self.lock:
            ecos = {e: {"records": self.state.get(e, {}).get("records", 0),
                        "wanted": len(self.wanted.get(e) or ()),
                        "last_fetched": self.state.get(e, {}).get("last_fetched"),
                        "last_error": self.state.get(e, {}).get("last_error")}
                    for e in OSV_ECOSYSTEMS.values()}
        return {"enabled": self.enabled, "mode": self.mode, "ecosystems": ecos}


_OSV_KEY_BY_NAME = {v: k for k, v in OSV_ECOSYSTEMS.items()}   # "PyPI"->"pypi", "npm"->"npm"



