def _parse_apt_upgrade(text):
    """Parse `apt-get -s upgrade` output. Each upgradable package is an 'Inst' line, e.g.
       Inst libfoo [1.0] (1.1 Ubuntu:22.04/jammy-security [amd64])
    Flag the ones whose target archive is a security pocket (jammy-security / bookworm-security /
    Debian-Security). Uses APT's cached lists, so it never hits the network."""
    out = []
    for line in (text or "").splitlines():
        if not line.startswith("Inst "):
            continue
        toks = line.split()
        if len(toks) < 2:
            continue
        name = toks[1]
        paren = line.split("(", 1)[1].lower() if "(" in line else ""
        out.append({"name": name, "security": ("security" in paren),
                    "line": line.strip()[:200]})
    return out


def _parse_dpkg_status(path):
    """Installed packages (name, version) from the dpkg status file — a pure file read, no
    dpkg-query subprocess (matching DpkgIndex). Only fully-installed entries are returned."""
    out = []
    try:
        with open(path, encoding="utf-8", errors="replace") as f:
            blob = f.read()
    except OSError:
        return out
    for para in blob.split("\n\n"):
        name = ver = status = None
        for line in para.splitlines():
            if line.startswith("Package: "):
                name = line[9:].strip()
            elif line.startswith("Version: "):
                ver = line[9:].strip()
            elif line.startswith("Status: "):
                status = line[8:].strip()
        if name and ver and status and status.endswith(" installed"):
            out.append({"name": name, "version": ver})
    return out


def _distro_family(osr):
    """Which package manager this distro uses, from /etc/os-release ID + ID_LIKE:
    'debian' (apt/dpkg), 'rhel' (dnf/rpm — Fedora/RHEL/Rocky/Alma/Amazon), 'alpine' (apk), or None."""
    toks = set((((osr.get("ID") or "") + " " + (osr.get("ID_LIKE") or "")).lower()).split())
    if toks & {"debian", "ubuntu"}:
        return "debian"
    if toks & {"rhel", "fedora", "centos", "rocky", "almalinux", "ol", "amzn"}:
        return "rhel"
    if "alpine" in toks:
        return "alpine"
    return None


def _nevra_name(nevra):
    """Package name from an RPM NEVRA or Alpine name-ver-rN (strip the trailing version + release)."""
    parts = (nevra or "").rsplit("-", 2)
    return parts[0] if len(parts) == 3 else (nevra or "")


def _parse_dnf_security(text):
    """Package names with a pending SECURITY advisory, from `dnf updateinfo list --security`
    (rows like 'RHSA-2024:1234 Important/Sec. bash-5.1.8-9.el9.x86_64')."""
    names = set()
    for line in (text or "").splitlines():
        p = line.split()
        if len(p) >= 3 and "sec" in p[1].lower():
            names.add(_nevra_name(p[-1].rsplit(".", 1)[0]))      # drop .arch, then NEVRA->name
    return names


def _parse_dnf_checkupdate(text, security_names=None):
    """Parse `dnf check-update` output (rows like 'bash.x86_64  5.1.8-9.el9  baseos')."""
    sec = security_names or set()
    out = []
    for raw in (text or "").splitlines():
        line = raw.rstrip()
        if not line or line[0].isspace() or line.startswith(("Obsoleting", "Last metadata", "Security:")):
            continue
        p = line.split()
        if len(p) < 3 or "." not in p[0]:
            continue
        name = p[0].rsplit(".", 1)[0]                            # strip .arch
        out.append({"name": name, "security": (name in sec), "line": line.strip()[:200]})
    return out


def _parse_apk_upgradable(text):
    """Parse `apk version -l '<'` (rows like 'busybox-1.36.1-r5 < 1.36.1-r7'). Alpine has no
    separate security channel, so nothing is flagged security here (all upgrades are from -stable)."""
    out = []
    for raw in (text or "").splitlines():
        line = raw.strip()
        if "<" not in line:
            continue
        left = line.split("<", 1)[0].strip()
        name = _nevra_name(left)
        if name:
            out.append({"name": name, "security": False, "line": line[:200]})
    return out


def _parse_rpm_qa(text):
    """Parse `rpm -qa --qf '%{NAME} %{VERSION}-%{RELEASE}\\n'` into {name, version}."""
    out = []
    for raw in (text or "").splitlines():
        p = raw.split()
        if len(p) >= 2:
            out.append({"name": p[0], "version": p[1]})
    return out


def _parse_apk_info(text):
    """Parse `apk info -v` (rows like 'busybox-1.36.1-r5') into {name, version}."""
    out = []
    for raw in (text or "").splitlines():
        s = raw.strip()
        if not s:
            continue
        name = _nevra_name(s)
        if name and len(name) < len(s):
            out.append({"name": name, "version": s[len(name) + 1:]})
    return out


class LinuxOSCurrency:
    """Distro/kernel currency + pending APT security updates — the authoritative Linux exposure
    signal (a security update exists precisely when a CVE has a distro fix available)."""

    def __init__(self):
        self.lock = threading.Lock()
        self._state = {}

    @staticmethod
    def _os_release():
        info = {}
        try:
            with open("/etc/os-release") as f:
                for line in f:
                    if "=" in line:
                        k, v = line.rstrip("\n").split("=", 1)
                        info[k] = v.strip().strip('"')
        except OSError:
            pass
        return info

    @staticmethod
    def _kernel():
        rc, out, _ = run(["uname", "-r"], timeout=5)
        return out.strip() if rc == 0 and out.strip() else None

    @staticmethod
    def _pending_updates(family):
        """Pending updates against the CACHED package lists — no network, no state change. Dispatched
        by distro family: apt (Debian/Ubuntu), dnf (RHEL family), apk (Alpine)."""
        if family == "rhel":
            rc, out, err = run(["dnf", "-q", "check-update"], timeout=120)
            if rc == 124:
                return None, "dnf timed out"
            if rc not in (0, 100):            # 100 = updates available; anything else = no data
                return None, (err or "dnf unavailable")[:160]
            src, sout, _ = run(["dnf", "-q", "updateinfo", "list", "--security"], timeout=120)
            sec = _parse_dnf_security(sout) if src == 0 else set()
            return _parse_dnf_checkupdate(out, sec), None
        if family == "alpine":
            rc, out, err = run(["apk", "version", "-l", "<"], timeout=30)
            if rc not in (0,):
                return None, (err or "apk unavailable")[:160]
            return _parse_apk_upgradable(out), None
        # default: Debian/Ubuntu (apt) — simulated upgrade
        rc, out, err = run(["apt-get", "-s", "upgrade"], timeout=60)
        if rc == 124:
            return None, "apt-get timed out"
        if rc not in (0, 100):
            return None, (err or "apt-get unavailable")[:160]
        return _parse_apt_upgrade(out), None

    @staticmethod
    def _reboot_required(family):
        if family == "rhel":
            rc, _, _ = run(["needs-restarting", "-r"], timeout=10)
            return rc == 1                       # 1 = reboot needed, 0 = not, other = tool missing
        return os.path.exists("/var/run/reboot-required")   # debian/ubuntu

    def check(self):
        osr = self._os_release()
        family = _distro_family(osr)
        pending, perr = self._pending_updates(family)
        state = {
            "distro": osr.get("NAME") or osr.get("ID"),
            "version": osr.get("VERSION_ID") or osr.get("VERSION"),
            "pretty": osr.get("PRETTY_NAME"),
            "family": family,
            "kernel": self._kernel(),
            "pending": pending or [],
            "pending_error": perr,
            "reboot_required": self._reboot_required(family),
            "checked": time.time(),
        }
        with self.lock:
            self._state = state
        return state

    @staticmethod
    def findings(state):
        pend = state.get("pending") or []
        if not pend:
            return []
        sec = [u for u in pend if u.get("security")]
        sev = "high" if sec else "medium"
        label = "%d pending package update%s" % (len(pend), "" if len(pend) == 1 else "s")
        if sec:
            label += " (%d security)" % len(sec)
        titles = [u.get("name") for u in pend if u.get("name")]
        detail = ", ".join(titles[:12])[:400]
        fam = state.get("family")
        tool = {"rhel": "dnf", "alpine": "apk"}.get(fam, "apt")
        refs = {"rhel": ["https://access.redhat.com/security/security-updates/",
                         "https://errata.rockylinux.org/"],
                "alpine": ["https://security.alpinelinux.org/"]}.get(
                    fam, ["https://ubuntu.com/security/notices", "https://www.debian.org/security/"])
        return [{
            "source": "os-update", "kind": "os_currency", "severity": sev,
            "component": state.get("pretty") or state.get("distro") or "Linux",
            "installed_version": state.get("version"),
            "title": label, "detail": detail,
            "description": ("%s reports these upgradable packages: %s. Security updates close known, "
                            "distro-fixed CVEs; apply them to stay current." % (tool, detail)),
            "references": refs,
            "cvss": None, "aliases": [], "published": None, "url": None,
            "fixed": None, "restart": bool(state.get("reboot_required")),
            "live": False, "remediation": None,
        }]


class LinuxSoftwareInventory:
    """Installed dpkg packages + globally-installed language packages (pip / npm)."""

    DPKG_STATUS = "/var/lib/dpkg/status"

    def __init__(self, osv="auto"):
        self.osv = (osv or "auto")

    def _want_eco(self, key):
        if self.osv == "off":
            return False
        if self.osv == "auto":
            return True
        return key in {m.strip().lower() for m in self.osv.split(",") if m.strip()}

    def _packages(self):
        out = []
        if self._want_eco("pypi"):
            out += _pip_packages()
        if self._want_eco("npm"):
            out += _npm_global_packages()
        return out

    @staticmethod
    def _native(family):
        """Installed OS packages for the distro family, tagged with the manager kind."""
        if family == "rhel":
            rc, out, _ = run(["rpm", "-qa", "--qf", "%{NAME} %{VERSION}-%{RELEASE}\n"], timeout=90)
            return (_parse_rpm_qa(out) if rc == 0 else []), "rpm"
        if family == "alpine":
            rc, out, _ = run(["apk", "info", "-v"], timeout=60)
            return (_parse_apk_info(out) if rc == 0 else []), "apk"
        return _parse_dpkg_status("/var/lib/dpkg/status"), "dpkg"

    def collect(self):
        family = _distro_family(LinuxOSCurrency._os_release())
        native, kind = self._native(family)
        pkgs = self._packages()
        out = {"native": native, "native_kind": kind, "packages": pkgs, "collected": time.time(),
               "counts": {kind: len(native), "packages": len(pkgs)}}
        if kind == "dpkg":
            out["dpkg"] = native              # back-compat alias for the Debian path
        return out


# Remediation states an operator can record against a finding. 'open' is the default (absence of a
# record). 'patched' is auto-verifying: it suppresses the finding until the next scan, which either
# confirms it (finding gone) or RE-OPENS it as a conflict (still detected after you said you patched).
# The others are standing decisions that keep the finding suppressed with your note.
VULN_REMEDIATION_STATES = ("patched", "mitigated", "accepted", "false_positive")


class VulnRemediationStore:
    """Per-finding remediation decisions, keyed by a stable finding signature and persisted to disk,
    so marking something patched / mitigated / accepted / a false positive survives rescans and
    restarts. Mirrors TriageStore for alerts."""

    def __init__(self, path=None):
        self.path = path or os.path.join(HERE, "vuln-remediation.json")
        self.lock = threading.Lock()
        self.data = {}          # sig -> {status, note, by, ts}
        self._load()

    def _load(self):
        try:
            with open(self.path) as f:
                d = json.load(f)
            if isinstance(d, dict):
                self.data = {k: v for k, v in d.items()
                             if isinstance(v, dict) and v.get("status") in VULN_REMEDIATION_STATES}
        except (OSError, ValueError):
            self.data = {}

    def _save(self):
        try:
            tmp = self.path + ".tmp"
            with open(tmp, "w") as f:
                json.dump(self.data, f)
            os.replace(tmp, self.path)
        except OSError:
            pass

    def set(self, sig, status, note=None, by=None):
        status = status if status in VULN_REMEDIATION_STATES else "open"
        with self.lock:
            if status == "open":                       # clearing a decision
                self.data.pop(sig, None)
                rec = None
            else:
                rec = {"status": status, "ts": int(time.time()),
                       "note": (str(note)[:1000] if note else None),
                       "by": (str(by)[:120] if by else None)}
                self.data[sig] = rec
            self._save()
        return rec

    def get(self, sig):
        with self.lock:
            r = self.data.get(sig)
            return dict(r) if r else None

    def prune(self, active_sigs):
        """Drop decisions whose finding is no longer detected (e.g. a 'patched' item that's now gone —
        verified resolved — or a 'mitigated' one that was also upgraded away)."""
        with self.lock:
            stale = [s for s in self.data if s not in active_sigs]
            for s in stale:
                self.data.pop(s, None)
            if stale:
                self._save()
            return len(stale)

    def all(self):
        with self.lock:
            return {k: dict(v) for k, v in self.data.items()}


class KevFeed:
    """Known-Exploited-Vulnerabilities feed, for exploitation-aware prioritization. A CVE that is
    *known exploited in the wild* is more urgent than one that only has a high CVSS, so KEV membership
    floats a finding to the top of the queue and (new KEV findings) raises an EDR alert regardless of
    severity.

    Prefers **VulnCheck KEV** (community-tier API token — a superset of CISA KEV that also carries
    exploitation evidence); with no token it falls back to the free **CISA KEV**. Either way it
    downloads the full catalogue on a daily timer and matches CVEs entirely locally — nothing about the
    host's inventory leaves the machine. The VulnCheck pull is one backup request + one S3 download per
    day, far under the community rate limit."""

    SECRET_ID = "vulncheck"
    KEY_ENV = "VULNCHECK_API_TOKEN"
    VC_BACKUP = "https://api.vulncheck.com/v3/backup/vulncheck-kev"
    CISA_URL = ("https://www.cisa.gov/sites/default/files/feeds/"
                "known_exploited_vulnerabilities.json")

    def __init__(self, enabled=True, interval=86400, secrets=None, cache_file=None):
        self.enabled = enabled
        self.interval = max(3600, interval)
        self.secrets = secrets or SecretStore()
        self.cache_file = cache_file or os.path.join(HERE, "kev-cache.json")
        self.lock = threading.Lock()
        self.kev = {}            # CVE (upper) -> {ransomware, cisa, due, added, name, source, refs}
        self.source = None       # 'vulncheck' | 'cisa' | None
        self.last = 0
        self.error = None
        self._load_cache()
        if enabled:
            threading.Thread(target=self._loop, daemon=True).start()

    # ---- token (GUI-settable, SecretStore; env is a read-only fallback) ----
    def has_token(self):
        return bool(self.secrets.get(self.SECRET_ID) or os.environ.get(self.KEY_ENV, "").strip())

    def _token(self):
        return self.secrets.get(self.SECRET_ID) or os.environ.get(self.KEY_ENV, "").strip() or None

    def token_source(self):
        if self.secrets.get(self.SECRET_ID):
            return self.secrets.backend_for(self.SECRET_ID)
        return "env" if os.environ.get(self.KEY_ENV, "").strip() else None

    def set_token(self, token):
        if self.token_source() == "env":
            return {"ok": False, "error": "token comes from $%s — unset the env var to manage it here"
                    % self.KEY_ENV}
        backend = self.secrets.set(self.SECRET_ID, token)
        threading.Thread(target=lambda: self.refresh(force=True), daemon=True).start()
        return {"ok": True, "stored": bool((token or "").strip()), "backend": backend}

    # ---- lookup / enrichment ----
    def lookup(self, cve):
        if not cve:
            return None
        with self.lock:
            return self.kev.get(str(cve).upper())

    def enrich(self, f):
        """Stamp KEV fields onto a finding / Shodan-vuln dict that carries a 'cve'."""
        rec = self.lookup(f.get("cve"))
        f["kev"] = bool(rec)
        if rec:
            f["kev_ransomware"] = bool(rec.get("ransomware"))
            f["kev_cisa"] = bool(rec.get("cisa"))
            f["kev_due"] = rec.get("due")
            f["kev_source"] = rec.get("source")
        return f

    # ---- persistence ----
    def _load_cache(self):
        try:
            with open(self.cache_file) as f:
                d = json.load(f) or {}
        except (OSError, ValueError):
            return
        if isinstance(d.get("kev"), dict):
            self.kev = {k.upper(): v for k, v in d["kev"].items() if isinstance(v, dict)}
            self.source = d.get("source")
            self.last = int(d.get("last") or 0)

    def _save_cache(self):
        try:
            tmp = self.cache_file + ".tmp"
            with open(tmp, "w") as f:
                json.dump({"kev": self.kev, "source": self.source, "last": self.last}, f)
            os.replace(tmp, self.cache_file)
        except OSError:
            pass

    # ---- download ----
    def _http(self, url, headers=None, timeout=60):
        req = urllib.request.Request(url, headers=headers or {"User-Agent": "Scouter-agent"})
        with urllib.request.urlopen(req, timeout=timeout) as r:
            return r.read()

    def _fetch_vulncheck(self, token):
        meta = json.loads(self._http(self.VC_BACKUP, headers={
            "User-Agent": "Scouter-agent", "Accept": "application/json",
            "Authorization": "Bearer " + token}, timeout=30).decode("utf-8", "replace"))
        rows = meta.get("data") or []
        url = rows[0].get("url") if rows else None
        if not url:
            raise ValueError("no backup URL in VulnCheck response")
        blob = self._http(url, timeout=120)                      # pre-signed S3 — NO auth header
        with zipfile.ZipFile(io.BytesIO(blob)) as z:
            name = next((n for n in z.namelist() if n.lower().endswith(".json")), None)
            if not name:
                raise ValueError("no JSON in VulnCheck KEV backup zip")
            doc = json.loads(z.read(name).decode("utf-8", "replace"))
        recs = doc.get("data") if isinstance(doc, dict) else doc
        out = {}
        for rec in (recs or []):
            if not isinstance(rec, dict):
                continue
            cves = rec.get("cve") or []
            if isinstance(cves, str):
                cves = [cves]
            info = {"ransomware": (rec.get("knownRansomwareCampaignUse") or "").lower() == "known",
                    "cisa": bool(rec.get("cisa_date_added")),
                    "due": rec.get("dueDate") or rec.get("cisa_date_added"),
                    "added": rec.get("date_added") or rec.get("cisa_date_added"),
                    "name": rec.get("vulnerabilityName"),
                    "vendor": rec.get("vendorProject") or rec.get("vendor"),
                    "product": rec.get("product"),
                    "refs": len(rec.get("vulncheck_reported_exploitation") or []),
                    "source": "vulncheck"}
            for c in cves:
                if c:
                    out[str(c).upper()] = info
        return out

    def _fetch_cisa(self):
        doc = json.loads(self._http(self.CISA_URL, timeout=60).decode("utf-8", "replace"))
        out = {}
        for rec in (doc.get("vulnerabilities") or []):
            c = rec.get("cveID")
            if not c:
                continue
            out[str(c).upper()] = {
                "ransomware": (rec.get("knownRansomwareCampaignUse") or "").lower() == "known",
                "cisa": True, "due": rec.get("dueDate"), "added": rec.get("dateAdded"),
                "name": rec.get("vulnerabilityName"),
                "vendor": rec.get("vendorProject"), "product": rec.get("product"),
                "refs": 0, "source": "cisa"}
        return out

    def refresh(self, force=False):
        if not self.enabled:
            return
        if not force and self.kev and (time.time() - self.last) < self.interval:
            return
        token = self._token()
        try:
            data = self._fetch_vulncheck(token) if token else self._fetch_cisa()
            src = "vulncheck" if token else "cisa"
            if data:
                with self.lock:
                    self.kev, self.source, self.last, self.error = data, src, int(time.time()), None
                self._save_cache()
            else:
                self.error = "KEV feed returned no records"
        except Exception as e:  # noqa: BLE001 — a feed hiccup must never break scanning
            self.error = "could not refresh KEV (%s): %s" % (token and "VulnCheck" or "CISA", e)

    def _loop(self):
        time.sleep(10)
        while True:
            try:
                self.refresh()
            except Exception:  # noqa: BLE001
                pass
            time.sleep(1800)

    def status(self):
        return {"enabled": self.enabled, "has_token": self.has_token(),
                "token_source": self.token_source(), "source": self.source,
                "count": len(self.kev), "last": self.last, "error": self.error}

    # ---- recently-exploited → threat-hunt query generation ----
    # Generic infrastructure, vendor, and vulnerability-description words that make a poor process-name
    # hunt (they match far too much), so they never become a keyword. Specific product/model tokens
    # (sma1000, netscaler, tomcat) and vendor names kept as a fallback (beyondtrust, ivanti) are NOT here.
    _HUNT_STOP = {
        "the", "for", "and", "server", "client", "manager", "manage", "management", "desktop",
        "edition", "enterprise", "windows", "microsoft", "apple", "google", "cisco", "adobe",
        "oracle", "system", "software", "products", "product", "multiple", "firewall", "router",
        "appliance", "appliances", "gateway", "framework", "library", "plugin", "core", "service",
        "services", "agent", "suite", "platform", "mobile", "cloud", "online", "web", "application",
        "applications", "linux", "kernel", "driver", "network", "remote", "support", "secure",
        "email", "access", "console", "portal", "central", "connect", "workplace", "side", "based",
        # vulnerability-description words, so the name fallback can't grab them
        "vulnerability", "vulnerabilities", "traversal", "injection", "overflow", "bypass",
        "spoofing", "improper", "input", "validation", "execution", "arbitrary", "authentication",
        "privilege", "escalation", "disclosure", "request", "forgery", "memory", "buffer", "bounds",
        "path", "relative", "missing", "encryption", "sensitive", "deserialization", "command",
        "restriction", "operations", "unauthenticated", "code", "within", "handling", "processing",
        "data", "errors", "error", "elevation", "privileges", "confusion", "condition", "race",
        "leak", "denial", "exposure", "hardcoded", "default", "credentials", "credential", "pointer",
        "dereference", "heap", "stack", "integer", "underflow", "double", "inclusion", "upload",
        "redirect", "scripting", "channel", "information", "uninitialized", "format", "string",
        "null", "write", "read", "type", "cross", "local", "control", "flaw", "issue", "insecure",
        "unrestricted", "unauthorized", "authorization", "session", "smuggling", "poisoning",
        "tampering", "hijacking", "free", "after", "allocation", "function", "method", "parameter",
    }

    @classmethod
    def hunt_keyword(cls, product, vendor, name=""):
        """A single conservative process-name token to hunt for, or None if nothing specific enough."""
        # Gather product/model noun candidates from all three fields, then prefer a token carrying a
        # digit (a model/version like sma1000, log4j2) over a plain word, then the longest. Product
        # tokens come first so they win ties over name/vendor.
        cand = []
        for src in (product, name, vendor):
            for t in re.split(r"[^A-Za-z0-9]+", (src or "").lower()):
                if len(t) >= 4 and t not in cls._HUNT_STOP and not t.isdigit():
                    cand.append(t)
        if not cand:
            return None
        vend = (vendor or "").strip().lower()
        # prefer a model/version token (digit-bearing), then the product-specific noun over the vendor
        # name (so "Apache Tomcat" hunts tomcat, not apache), then the longest.
        return max(cand, key=lambda t: (any(c.isdigit() for c in t), t != vend, len(t)))

    @staticmethod
    def hunt_sql(kw):
        """Read-only hunt: running processes AND recent executions whose name/path/args mention kw."""
        like = "%" + kw.replace("'", "''").lower() + "%"
        return ("-- Running processes and recent executions mentioning '%s'\n" % kw
                + "SELECT 'running' AS seen, name, exe, cmdline,\n"
                  "       datetime(last_seen,'unixepoch','localtime') AS t\n"
                  "FROM processes\n"
                  "WHERE lower(name) LIKE '{l}' OR lower(exe) LIKE '{l}' OR lower(cmdline) LIKE '{l}'\n"
                  "UNION ALL\n"
                  "SELECT 'executed' AS seen, '' AS name, exe, cmdline,\n"
                  "       datetime(ts,'unixepoch','localtime') AS t\n"
                  "FROM exec_events\n"
                  "WHERE lower(exe) LIKE '{l}' OR lower(cmdline) LIKE '{l}'\n"
                  "ORDER BY t DESC".format(l=like))

    def recent(self, days=14):
        """KEV entries added within the last `days`, newest first."""
        cutoff = time.time() - days * 86400
        out = []
        with self.lock:
            items = list(self.kev.items())
        for cve, rec in items:
            added = (rec.get("added") or "")[:10]
            try:
                ts = time.mktime(time.strptime(added, "%Y-%m-%d"))
            except (ValueError, TypeError):
                continue
            if ts >= cutoff:
                out.append((ts, cve, rec))
        out.sort(key=lambda x: -x[0])
        return [(cve, rec) for _ts, cve, rec in out]

    def hunt_suggestions(self, days=14, host_tokens=None, limit=40):
        """Pre-built threat-hunt queries for recently-exploited (KEV, last `days`) CVEs that map to a
        usable product keyword, on_host ones first, then ransomware-linked, then most-recent."""
        host_tokens = {t.lower() for t in (host_tokens or set()) if t}
        seen_kw, out = set(), []
        for cve, rec in self.recent(days):
            kw = self.hunt_keyword(rec.get("product"), rec.get("vendor"), rec.get("name"))
            if not kw or kw in seen_kw:
                continue
            seen_kw.add(kw)
            on_host = any(kw == t or kw in t or t in kw for t in host_tokens)
            out.append({"cve": cve, "name": rec.get("name"), "vendor": rec.get("vendor"),
                        "product": rec.get("product"), "keyword": kw, "sql": self.hunt_sql(kw),
                        "ransomware": bool(rec.get("ransomware")), "added": (rec.get("added") or "")[:10],
                        "source": rec.get("source"), "on_host": on_host})
        out.sort(key=lambda h: (not h["on_host"], not h["ransomware"], _neg_date(h["added"])))
        return out[:limit]


def _neg_date(d):
    """Sort key so a more-recent YYYY-MM-DD comes first within a group."""
    try:
        return -time.mktime(time.strptime(d, "%Y-%m-%d"))
    except (ValueError, TypeError):
        return 0


